		\begin{itemize}
			\item[(a)] If $\deg(A)-\deg(C) \leq 1$, then \eqref{ecu1} has at most one invariant curve. 
			\item[(b)] If $\deg(A)-\deg(C) > 1$ and we are either in the polynomial case, or in the trigonometric one with $C(t)$ non-constant, then
			\begin{itemize}
				\item[(b.1)] If $\deg(A)-\deg(C)$ is odd or $\deg(A)+\deg(C) <  2 \deg(B)$, then \eqref{ecu1} has at most two invariant curves.
				\item[(b.2)] If $\deg(A)-deg(C)$ is even and $\deg(A)+\deg(C) \geq 2 \deg(B)$, then,
				\begin{itemize}
					\item[(b.2.1)]  in the polynomial case, the number of invariant curves of \eqref{ecu1} is at most \[\binom{\deg(A)}{(\deg(A)+1)/2}+1.\] Moreover, in this case, \eqref{ecu1} is Darboux integrable, if the number of invariant curves of \eqref{ecu1} is greater that $\deg(A)+\deg(C)+4$.
					\item[(b.2.2)] in the trigonometric case, an upper bound for the number of rational limit cycles of \eqref{ecu1} is $2\deg(A)+2\deg(C)+4$.
				\end{itemize}
			\end{itemize}
			\item[(c)] If $\deg(A)-\deg(C) > 1$, in the trigonometric case and with $C(t)\equiv c$ a non zero constant, then an upper bound for the number of invariant curves is  $4\deg(A)$.
		\end{itemize}

