theorem.content:
\label{thm:phase-transition}
Let $\cC$ be a block-stable class of connected graphs, let $\cB$ be its class of $2$-connected components whose EGF we denote by $B(y)$, and let $\rho_B$ be the radius of convergence of $B$. Let
\[u_C := \frac{1}{\rho_B B''(\rho_B)}.\]
Then the following hold. 
\begin{itemize}
    \item The singular behaviour of $C^{\bullet}(x,u)$ depends on the relative positions of $u$ and $u_C$;
    \item The block tree corresponding to a graph drawn according to $\Pnu$ follows a subcritical \BGW{} tree law if $u<u_C$, and a critical \BGW{} tree law if $u \ge u_C$.
\end{itemize}

ref_dict.thm:block-sizes:
\begin{theorem}\label{thm:block-sizes}
There is a phase transition for block sizes depending on the value of $u$:
\begin{itemize}
    \item In the subcritical phase $u < u_C$, there is a largest block of size $\Theta_\mathbb{P}(n)$ and a second largest block of size $\Theta_\mathbb{P}(n^{2/3})$;
    \item In the critical phase $u = u_C$, there is a largest block of size $\Theta_\mathbb{P}(n^{2/3})$ and likewise for the next largest block sizes;
    \item In the supercritical phase $u > u_C$, there is a largest block of size $\Theta_\mathbb{P}(\ln (n))$ and likewise for the next largest block sizes.
\end{itemize}
\end{theorem}

ref_dict.thm:phasetransition_block_sizes:
\begin{theorem}\label{thm:phasetransition_block_sizes} Let $u>0$. The block-weighted graph $\Gnu$ exhibits the following behaviours when $n\to\infty$.
\begin{description}
    \item[Subcritical case.] If $u<u_C$, then \cref{th-taille-blocs-sous-crit}  holds for block sizes:
    \begin{align*}
    \frac{1}{(c(u) n)^{2/3}}&\(\(1-\frac{u}{u_C}\)n - \LB{1}{\Gnu}, \(\LB{j}{\Gnu} : j\geq 2\)\) \\
    &\hspace{170pt} \xrightarrow[n\to\infty]{(d)} \(L_1,\(\Delta L_{(j-1)} : j\geq 2\)\)
    \end{align*}
    where $(L_t)_{t\in[0,1]}$ is a stable process of parameter $3/2$ such that $\E{e^{-sL_1}} = e^{\Gamma(-3/2)s^{3/2}}$ and $\Delta L_{(1)} \geq \Delta L_{(2)} \geq \dots$ is the ranked sequence of its jumps.

    \item[Critical case.] If $u=u_C$, then \cref{eq:size-bloc-critical} holds for the block sizes:
    \[\(\frac{\LB{j}{\G_{n,u_C}}}{n^{2/3}} : j \geq 1\) \xrightarrow[n\to\infty]{(d)} \(E_{(j)} : j \geq 1\),\]
    where the $E_{(j)}$ are as defined in \cref{prop:degrees-Tnu}.
    \item[Supercritical case.] If $u>u_C$, then \cref{eq:grandbloc} holds for the block sizes (fixing $j \in \mathbb{N}_0$):
    \[\LB{j}{\Gnu} = \frac{\ln(n)}{\ln\(\frac{\rho_B}{y(u)}\)} - \frac{5}{2}\frac{\ln(\ln(n))}{\ln\(\frac{\rho_B}{y(u)}\)} + O_{\mathbb{P}}(1).\]
\end{description}
\end{theorem}

