\]
\end{remark}

The analysis relies on the relative entropy method, uniform Sobolev estimates and compactness arguments, which allow us to rigorously justify the convergence of solutions of the compressible system toward the limit system as $\eps \to 0$. Our work provides a mathematical foundation for the incompressible regime of two-phase models with algebraic closure and single velocity, and clarifies the structure of the low Mach number limit in this context.

This paper is organized as follows. In Section~\ref{relative_entropy}, we introduce our relative entropy functional which consists of a classical contribution and an additional component based on a logarithmic comparison of the partial densities. In Section~\ref{useful_ineq}, we exploit the special structure of the bi-fluid system to derive several key inequalities, including an original comparison between the $L^1$ and $L^2$ norms of the partial densities and a variant of the Csiszár--Kullback--Pinsker inequality. Next, in Section~\ref{convR}, we prove the strong convergence of the partial densities, and finally, Section~\ref{End} completes the proof of our main theorem.

\section{Relative entropy}\label{relative_entropy}

In this section, we introduce the relative entropy functional that will be our main tool to prove Theorem \ref{mainth}.

\subsection{Definition}

We derive a relative entropy between a weak solution $(\rho^{\epsilon}_+,\rho^{\epsilon}_-,\alpha^{\epsilon}_+,u^{\epsilon})$ of System \eqref{system_eps}, in the sense of Definition \ref{defp} below, and any other state $(\rho_+,\rho_-,\alpha_+,u)$ of the fluid. Let us consider the relative energy functional,
denoted by $ \EE_1(\rho^{\epsilon}_+,\rho^{\epsilon}_-,\alpha^{\epsilon}_+,u^{\epsilon}|\rho_+,\rho_-,\alpha_+,u)$ and defined as:

\begin{align}\label{EE1}
    \begin{split}
        \EE_1 \Big(\rho^{\epsilon}_+,\rho^{\epsilon}_-,\alpha^{\epsilon}_+,u^{\epsilon}|\rho_+,\rho_-,\alpha_+,u\Big) =& \int_{\Omega}  \frac{1}{2} (\alpha^{\epsilon}_+\rho^{\epsilon}_+ + \alpha^{\epsilon}_-\rho^{\epsilon}_-) |u^{\epsilon} - u|^2 \\ 
        &+ \int_{\Omega} \frac{\alpha_+^{\epsilon}}{\epsilon^2} H(\rho_+^\eps | \rho_+) + \int_{\Omega} \frac{\alpha_-^{\epsilon}}{\epsilon^2} H(\rho_-^\eps | \rho_-),
    \end{split}
\end{align}
with, for $i=+,-$,
\begin{align}\label{H}
    H(\rho_i^\eps | \rho_i) := \frac{1}{\gamma_i-1}  \left( (\rho_i^{\epsilon})^{\gamma_i} - \rho_i^{\gamma_i} - \gamma_i\rho_i^{\gamma_i-1}(\rho_i^{\epsilon}-\rho_i) \right).
\end{align}

In order to control the $L^1$ norm of the partial densities and close the Gronwall argument required for the proof of Theorem~\ref{mainth}, we introduce the following functional
\begin{align}\label{EE2}
    \begin{split}
        \EE_2 \Big(\rho^{\epsilon}_+,\rho^{\epsilon}_-,\alpha^{\epsilon}_+,u^{\epsilon}|\rho_+,\rho_-,\alpha_+,u\Big) = \int_\Omega R_+^\eps \ln_+ \left( \frac{R_+^\eps}{R_+} \right) + \int_\Omega R_-^\eps \ln_+ \left( \frac{R_-^\eps}{R_-} \right).\\
    \end{split}
\end{align}
and we set $\ln_+ s = \max(0,\ln s)$.

Finally, we define the total relative entropy functional:
\begin{align*}
    \EE \Big(\rho^{\epsilon}_+,\rho^{\epsilon}_-,\alpha^{\epsilon}_+,u^{\epsilon}| \rho_+,\rho_-,\alpha_+,u\Big) = (\EE_1 + \EE_2 ) \Big(\rho^{\epsilon}_+,\rho^{\epsilon}_-,\alpha^{\epsilon}_+,u^{\epsilon}| \rho_+,\rho_-,\alpha_+,u\Big).
\end{align*}

In this definition, we always set $\alpha_-^\eps = 1-\alpha_+^\eps$ and $\alpha_- = 1-\alpha_+$.

The goal of the next subsection is to study the evolution of this entropy for the weak solution of System \eqref{system_eps} in the following sense. 

