\begin{remark}\label{rkalpha}
When we consider $(\rho, u)$ a regular solution to non-homogeneous viscous incompressible Navier-Stokes equations, it is clear that we may construct a solution of \eqref{limitsys}. Indeed, solving $\rho=\rho_+ \alpha_+ + \rho_- \alpha_-$ and $1= \alpha_+ + \alpha_-$, we simply define
\[
\alpha_+ = \frac{\rho - \rho_-}{\rho_+-\rho_-} \quad\text{and}\quad \alpha_- = -\frac{\rho - \rho_+}{\rho_+-\rho_-}
\]
which is well defined for $\gamma_+\neq \gamma_-$, as $C_0>0$. We observe that $\alpha_\pm$ satisfy the transport equation. Assuming initially $\alpha_{\pm,0}\in [\underline{a},\bar{a}]\subset (0,1)$, such a property then remains true. Let us notice that we can express $\underline{C}$ and $\overline{C}$ in terms of $\underline{a},\overline{a},C_0,\gamma_\pm$.
\end{remark}

\begin{remark}
We will consider $s=3$. The existence result stated above is not optimal in terms of regularity for our subsequent arguments. For our purposes, a lower level of regularity would suffice, but this is not relevant here.
\end{remark}

\subsection{Main theorem}

We can now state the main result of this paper, where we denote the fractional masses of the limit system by $R_{\pm 0} = \alpha_{\pm, 0} \rho_{\pm, 0}$.

\begin{theorem}
    [Singular limit of the compressible two-phase system]\label{mainth} Let $C>0$, $\gamma_\pm\geqslant 2$ be three real numbers and $\alpha_{\pm,0}$ be two functions such that $\gamma_+\neq \gamma_-$ and $0<\underline{a}\leqslant \alpha_{\pm,0} \leqslant \overline{a} <1$. Let us assume that $(\alpha_{\pm,0},u_0)$ are enough regular such that we can apply Theorem \ref{simon} for the initial data $(\rho_0,u_0)$, and let $T>0$ be the existence time of strong solution to System \eqref{limitsys}.

For each $\varepsilon>0$, let $(\rho_{+,0}^\varepsilon, R_{+,0}^\varepsilon, m_0^\varepsilon)\in L^{\gamma_+}\times L^{\gamma_+}\times L^1$ such that compatibility conditions \eqref{compatibilityeps} are verified and the total masses are consistent with the limit:
\begin{align}\label{totmas}
\int_\Omega R_{\pm,0}^\varepsilon \, dx = \int_\Omega R_{\pm,0} \, dx >0.
\end{align}

Assume that
\begin{enumerate}[(i)]
    \item the initial energy is uniformly bounded, namely
    \begin{align}
        \int_{\Omega} \frac{1}{2} \Big(\rho^\eps_0 |u^\eps_0|^2\Big)(x) \,\mathrm{d} x+\int_{\Omega} \frac{\alpha_{+,0}^\varepsilon \rho_{+,0}^{\varepsilon \gamma_{+}}(x)}{\varepsilon^2(\gamma_{+}-1)} \,\mathrm{d} x +\int_{\Omega} \frac{\alpha_{-,0}^\varepsilon \rho_{-,0}^{\varepsilon \gamma_{-}}(x)}{\varepsilon^2(\gamma_--1)} \,\mathrm{d} x \leqslant C,\label{ineq_E0}
    \end{align}
    and   
    \begin{align}\label{ineq_R0}
    \int_\Omega R_{+,0}^\varepsilon \ln_+ \frac{R_{+,0}^\varepsilon}{R_{+,0}} + \int_\Omega R_{-,0}^\varepsilon \ln_+ \frac{R_{-,0}^\varepsilon}{R_{-,0}} \leqslant C,
    \end{align}
where, here and below, $C$ denotes positive constants independent of $\varepsilon$,
    \item the initial data is well prepared, in the sense
    \begin{align}\label{ineq_EE10}
    \begin{split}
&\int_\Omega \frac{1}{2} \big(R^\varepsilon_{+,0} + R^\varepsilon_{-,0}\big) |u_0^\varepsilon - u_0|^2 \, dx\\
&\quad + \int_\Omega \frac{\alpha_{+,0}^\varepsilon}{\varepsilon^2 (\gamma_+-1)} \Big((\rho_{+,0}^\varepsilon)^{\gamma_+} - \rho_{+,0}^{\gamma_+} - \gamma_+ \rho_{+,0}^{\gamma_+-1} (\rho_{+,0}^\varepsilon - \rho_{+,0}) \Big) \, dx \\
&\quad + \int_\Omega \frac{\alpha_{-,0}^\varepsilon}{\varepsilon^2 (\gamma_--1)} \Big((\rho_{-,0}^\varepsilon)^{\gamma_-} - \rho_{-,0}^{\gamma_-} - \gamma_- \rho_{-,0}^{\gamma_--1} (\rho_{-,0}^\varepsilon - \rho_{-,0}) \Big) \, dx \longrightarrow 0.
\end{split}
    \end{align}
as $\varepsilon \to 0$.
\end{enumerate}

Then, the corresponding weak solution $(\rho_\pm^\varepsilon, \alpha_\pm^\varepsilon, u^\varepsilon)$ of the compressible two-phase Navier--Stokes system \eqref{system_eps}  on $(0,T)$, in the sense of Definition \ref{defp}, converge strongly to the incompressible limit as $\varepsilon \to 0$, namely
\begin{align}
R_\pm^\varepsilon &\longrightarrow R_\pm  &&\text{strongly in } L^\infty(0,T; L^2(\Omega)),
 \\
\rho_\pm^\varepsilon &\longrightarrow \rho_\pm &&\text{strongly in } L^\infty(0,T; L^2(\Omega)),\\
\alpha_\pm^\varepsilon &\longrightarrow \alpha_\pm &&\text{weak-$*$ in } L^\infty(0,T; L^2(\Omega)),\\
u^\varepsilon &\longrightarrow u &&\text{strongly in } L^2(0,T; L^2(\Omega)),\\
\nabla u^\varepsilon &\rightharpoonup \nabla u &&\text{weakly in } L^2(0,T; L^2(\Omega)),\\
\operatorname{div} u^\varepsilon &\rightharpoonup 0 &&\text{weakly in } L^2(0,T; L^2(\Omega)).
\end{align}
\end{theorem}

\begin{remark}
Assumptions \eqref{ineq_EE10} corresponds to the standard notion of \emph{well-prepared initial data} for the singular limit, as in \cite{lions1998incompressible}. They ensure that the initial deviations from the incompressible limit are sufficiently small to control the energy estimates uniformly in $\varepsilon$.
\end{remark}

\begin{remark}\label{rk.consmass}
The assumption \eqref{totmas} is preserved along the time by conservation of mass:
\[
\int_\Omega R_\pm^\varepsilon(t,x) \, dx = \int_\Omega R_{\pm,0}^\varepsilon(x) \, dx,
\qquad
\int_\Omega R_\pm(t,x) \, dx = \int_\Omega R_{\pm,0}(x) \, dx, \qquad \text{for all } t\in (0,T).
\]
\end{remark}

The analysis relies on the relative entropy method, uniform Sobolev estimates and compactness arguments, which allow us to rigorously justify the convergence of solutions of the compressible system toward the limit system as $\varepsilon \to 0$. Our work provides a mathematical foundation for the incompressible regime of two-phase models with algebraic closure and single velocity, and clarifies the structure of the low Mach number limit in this context.

