\begin{theorem}\label{thm:mixed}
    For any $d \ge 1$ and $\beta > 0$, there exist a $\beta$-smooth, $1/(1+1/\beta)$-strongly convex set $S_\beta$ and a $1$-smooth, $1$-strongly convex function $f_\beta$ such that every \texttt{LMO-span} method applied to $(f_\beta, S_\beta)$ starting from $x_0 = 0$ has for all $t\leq d-1$
    \begin{equation}
        f_\beta(x_t) - \min_{x\in S_\beta}f_\beta(x) \geq \max\left(0,\sqrt{\frac{2}{5}\frac{(d-t)(\mathrm{diam}(S_\beta) -  2/\beta)^2}{(d+2)^3}} - \frac{1}{\sqrt{2}\beta}\right)^2  . 
    \end{equation}
    In particular, for any fixed budget $T \ge 1$, there exist $S_\beta$ and $f_\beta$ in dimension $d=2(T+1)$ such that
    \[
        f_\beta(x_T) - \min_{x\in S_\beta}f_\beta(x) \geq \max\left(0,\frac{\mathrm{diam}(S_\beta) - 2/\beta}{\sqrt{20}(T+2)} - \frac{1}{\sqrt{2}\beta }\right)^2  .
    \]
\end{theorem}

