\appendix

\section{Complements on \texorpdfstring{$\infty$}{∞}-topoi}\label{app:complements_on_topoi}

In the main body of this note, we needed a few results from the theory of coherent \topoi that are not hard, but not easily citeable from the literature.
Since some parts of the theory get quite technical, for the convenience of the reader, we recall the necessities in this appendix.
In \cref{subsec:bounded_and_Postnikov_complete_topoi}, we recall background on bounded and Postnikov complete \topoi.
This is mostly not needed in this note, but we prove some technical lemmas that allow us to state a few results more cleanly in the main body.
In \cref{subsec:coherent_topoi_and_pretopoi}, we recall the basics of coherent \topoi and the classification of bounded coherent \topoi in terms of \pretopoi.
Finally, \Cref{subsec:spectral_topoi} recalls the theory of spectral \topoi introduced in our work with Barwick and Glasman \cite{arXiv:1807.03281}.

\subsection{Bounded and Postnikov complete \texorpdfstring{$\infty$}{∞}-topoi}\label{subsec:bounded_and_Postnikov_complete_topoi}

Now we recall two technical conditions on \topoi that make an appearance in our proofs: \textit{boundedness} and \textit{Postnikov completeness}.
They both guarantee that the \topos is controlled by its full subcategory of truncated objects, and are particular to the theory of \topoi (meaning there is no analogue in $ 1 $-topos theory).
The reader should refer to \cite[\SAGsec{A.7}]{SAG} for full details, or to \cite[Chapter 3]{arXiv:1807.03281} for a more detailed overview than the one provided here.

For boundedness, we first recall a bit about \textit{$ n $-localic \topoi}.
The idea is that $ n $-localic \topoi are the \topoi that are determined by their underlying $ n $-topoi of $ (n-1) $-truncated objects.

\begin{notation}
	Given \atopos $ \Xcal $ and integer $ n \geq -2 $, we write $ \Xcal_{\leq n} \subset \Xcal $ for the full subcategory spanned by the $ n $-truncated objects.
	The inclusion $ \Xcal_{\leq n} \inclusion \Xcal $ admits a left adjoint $ \trun_{\leq n} \colon \Xcal \to \Xcal_{\leq n} $ called \defn{$ n $-truncation}.
	We write $ \Xcal_{<\infty} \colonequals \Union_{n \geq -2} \Xcal_{\leq n} $ for the full subcategory spanned by the truncated objects.
\end{notation}

\begin{definition}[{\cite[\HTTsubsec{6.4.5}]{HTT}}]\label{def:n-localic_topoi}
	Let $ n \geq 0 $ be an integer.
	We say that \atopos $ \Xcal $ is \defn{$ n $-localic} if for every \topos $ \Ycal $, the natural functor
	\begin{equation*}
		\Funlowerstar(\Ycal,\Xcal) \to \Funlowerstar(\Ycal_{\leq n-1},\Xcal_{\leq n-1})
	\end{equation*}
	is an equivalence of \categories.
	The inclusion of the full subcategory of $ \RTop $ spanned by the $ n $-localic \topoi admits a left adjoint $ \Lup_n $.
	We call $ \Lup_n(\Xcal) $ the \defn{$ n $-localic reflection} of $ \Xcal $.
\end{definition}

\begin{nul}\label{nul:n-localic_in_terms_of_sites}
	The proof of \HTT{Proposition}{6.4.5.9} demonstrates that \atopos $ \Xcal $ is $n$-localic if and only if there exists a small $n$-site \textit{with all finite limits} $(\Ccal,\tau)$ and an equivalence $ \Xcal \equivalent \Sh_{\tau}(\Ccal)$.
\end{nul}

\begin{recollection}[{(boundedness)}]\label{rec:bounded_topoi}
	Let $ \Xcal $ be \atopos.
	The \defn{bounded reflection} of $ \Xcal $ is the cofiltered limit
	\begin{equation*}
		\Xcal^{\b} \colonequals \lim_{n \in \NN^{\op}} \Lup_n(\Xcal)
	\end{equation*}
	formed in $ \RTop $.
	We say that $ \Xcal $ is \defn{bounded} if the natural geometric morphism $ \blowerstar \colon \Xcal \to \Xcal^{\b} $ is an equivalence.
	The assignment $ \Xcal \mapsto \Xcal^{\b} $ is left adjoint to the inclusion of the full subcategory of $ \RTop $ spanned by the bounded \topoi \SAG{Proposition}{A.7.1.5}.
\end{recollection}

The second condition is defined in terms of the \categories $ \Xcal_{\leq n} $ of $ n $-truncated objects directly.
Note that these subcategories are not themselves \topoi.

\begin{recollection}[(Postnikov completeness)]\label{rec:Postnikov_completeness}
	Let $ \Xcal $ be \atopos.
	The \defn{Postnikov completion} of $ \Xcal $ is the limit 
	\begin{equation*}
		\Xcal^{\post} \colonequals  \lim \bigg(
		\begin{tikzcd}[sep=1.5em]
			\cdots \arrow[r] & \Xcal_{\leq n+1} \arrow[r, "\trun_{\leq n}"] & \Xcal_{\leq n} \arrow[r] & \cdots \arrow[r, "\trun_{\leq 0}"] & \Xcal_{\leq 0} 
		\end{tikzcd}\bigg)
		\index[notation]{Cpost@$C^{\post}$}
	\end{equation*}
	formed in \categories.
	We write $ \tupperstar \colon \Xcal \to \Xcal^{\post} $ for the natural comparison functor.
	We say that the \topos $ \Xcal $ is \defn{Postnikov complete} if $ \tupperstar \colon \Xcal \to \Xcal^{\post} $ is an equivalence.

	The Postnikov completion $ \Xcal^{\post} $ is also \atopos; moreover, $ \tupperstar \colon \Xcal \to \Xcal^{\post} $ is a left exact left adjoint \SAG{Theorem}{A.7.2.4}.
	The assignment $ \Xcal \mapsto \Xcal^{\post} $ is right adjoint to the inclusion of the full subcategory of $ \RTop $ spanned by the Postnikov complete \topoi 
	\SAG{Corollary}{A.7.2.6}.
	Moreover, the functors $ \Xcal \mapsto \Xcal^{\post} $ and $ \Xcal \mapsto \Xcal^{\b} $ define inverse equivalences between the full subcategories of $ \RTop $ spanned by the bounded and Postnikov complete \topoi \SAG{Corollary}{A.7.2.6}.

	In summary, if we write $ \RTop^{\b} $ and $ \RTop^{\post} $ for the full subcategories of $ \RTop $ spanned by the bounded and Postnikov complete coherent \topoi, respectively, we have the following diagram
	\begin{equation*}
		\begin{tikzcd}[column sep=4em, row sep=3em]
			\RTop^{\post} \arrow[dr, hooked, shift right] \arrow[rr, "\sim"'{yshift=0.25ex}, "{(-)^{\b}}", shift left] & & \RTop^{\b} \arrow[dl, hooked', shift left] \arrow[ll, shift left, "{(-)^{\post}}"{xshift=0.8ex}] \\
			& \RTop \arrow[ur, "{(-)^{\b}}"{xshift=1ex, yshift=-0.5ex}, shift left] \arrow[ul, "{(-)^{\post}}"'{xshift=-0.5ex, yshift=-0.5ex}, shift right] & \phantom{\RTop^{\b}} \period
		\end{tikzcd}
	\end{equation*}
	In particular, for any \topos $ \Xcal $, there are natural identifications
	\begin{equation*}
		\Xcal^{\b} = (\Xcal^{\post})^{\b} \andeq \Xcal^{\post} = (\Xcal^{\b})^{\post} \period
	\end{equation*}
\end{recollection}

\begin{observation}\label{obs:Xpost_Xbdd_and_X_have_the_same_truncated_objects}
	Let $ \Xcal $ be \atopos.
	Then the natural geometric morphisms
	\begin{equation*}
		\Xcal^{\post} \to \Xcal \to \Xcal^{\b}
	\end{equation*}
	restrict to equivalences 
	\begin{equation*}
		(\Xcal^{\post})_{<\infty} \equivalence \Xcal_{<\infty} \equivalence (\Xcal^{\b})_{<\infty}
	\end{equation*}
	on truncated objects.
	See \cite[\SAGthm{Lemma}{A.7.1.4} \& \SAGthm{Proposition}{A.7.3.7}]{SAG}.
\end{observation}

\begin{example}
	For any small \category $ \Ccal $, the \topos $ \PSh(\Ccal) $ of presheaves on $ \Ccal $ is Postnikov complete.
\end{example}

\begin{example}
	If $ X $ is a paracompact topological space of finite covering dimension or a spectral space of finite Krull dimension, then $ \Sh(X) $ is Postnikov complete \cites[\HTTthm{Corollary}{7.2.1.12}, \HTTthm{Theorem}{7.2.3.6} \& \HTTthm{Remark}{7.2.4.18}]{HTT}[Theorem 3.12]{MR4296353}.
	In particular, the \topos of sheaves on a profinite set is Postnikov complete.
\end{example}

\begin{example}[{\cite{MO:168526}}]
	Let $ X $ be a topological space.
	If $ X $ admits a CW structure, then the \topos $ \Sh(X) $ is Postnikov complete.
\end{example}

\subsection{Coherent \texorpdfstring{$\infty$}{∞}-topoi and \texorpdfstring{$\infty$}{∞}-pretopoi}\label{subsec:coherent_topoi_and_pretopoi}

We now recall the basics of coherent \topoi and the classification of bounded coherent \topoi in terms of \pretopoi.
The reader should refer to \cite[\SAGapp{A}]{SAG} for full details, or to \cite[Chapter 3]{arXiv:1807.03281} for a more detailed overview than the one provided here.

\begin{definition}[(coherence)]\label{rec:coherence}
	Let $ \Xcal $ be \atopos.
	We say that $\Xcal $ is \defn{$ 0 $-coherent} (or \defn{quasicompact}) if for every effective epimorphism $ e \colon \coprod_{i \in I} U_i \surjection 1_{\Xcal} $, there exists a finite subset $ I_0 \subset I $ such that the restriction $ \coprod_{i \in I_0} U_i \surjection 1_{\Xcal} $ of $ e $ is still an effective epimorphism.
	Let $ n \geq 0 $, and define $n$-coherence of \topoi and their objects recursively as follows.
	\begin{enumerate}
		\item An object $U\in \Xcal $ is \defn{$n$-coherent} if the \topos $\Xcal_{/U}$ is $n$-coherent.

		\item The \topos $\Xcal $ is \defn{locally $n$-coherent} if every object $U\in \Xcal $ admits a cover $\{\fromto{V_i}{U}\}_{i\in I}$ in which each $V_i$ is $n$-coherent.

		\item The \topos $\Xcal $ is \defn{$(n+1)$-coherent} if $ \Xcal $ is locally $n$-coherent, and the $n$-coherent objects of $\Xcal $ are closed under finite products.
	\end{enumerate}

	An \topos $\Xcal $ is \defn{coherent} if for each $ n \geq 0 $, the \topos $ \Xcal $ is $n$-coherent.
	An object $U$ of \atopos $\Xcal $ is \defn{coherent} if $\Xcal_{/U}$ is a coherent \topos.
	Finally, \atopos $\Xcal $ is \defn{locally coherent} if every object $U\in \Xcal $ admits a cover $\{\fromto{V_i}{U}\}_{i\in I}$ in which each $V_i$ is coherent.
\end{definition}

\begin{notation}
	Let $\Xcal $ be \atopos. 
	Write $ \Xcal^{\coh} \subset \Xcal $ for the full subcategory of $ \Xcal $ spanned by the coherent objects and $ \Xcal\cohtrun \subset \Xcal $ for the full subcategory of $ \Xcal $ spanned by the truncated coherent objects. 
\end{notation}

\begin{definition}[(coherent geometric morphism)]\label{def:coherent_geometric_morphism}
	A geometric morphism between coherent \topoi $ \flowerstar \colon \Ycal \to \Xcal $ is \defn{coherent} if, for each coherent object \smash{$ U \in \Xcal $}, the object $ \fupperstar(U) \in \Ycal $ is coherent.
	This is equivalent to the requirement that $ \fupperstar $ carries $ \Xcal\cohtrun $ to $ \Ycal\cohtrun $ \cite[Corollary 3.4.5]{arXiv:1807.03281}.
\end{definition}

\begin{recollection}[(coherence is detected on Postnikov completions and bounded reflections)]\label{rec:coherence_is_detected_on_Postnikov_completions_and_bounded_reflections}
	Given \atopos $ \Xcal $, the natural geometric morphisms $ \Xcal^{\post} \to \Xcal \to \Xcal^{\b} $ restrict to equivalences 
	\begin{equation*}
		(\Xcal^{\post})\cohtrun \equivalence \Xcal\cohtrun \equivalence (\Xcal^{\b})\cohtrun \period
	\end{equation*}
	Moreover, $ \Xcal $ is coherent if and only if $ \Xcal^{\post} $ is coherent if and only if $ \Xcal^{\b} $ is coherent.
	See \cite[Lemma 3.4.12]{arXiv:1807.03281}.
	In addition, if $ \Xcal $ and $ \Ycal $ are coherent, then a geometric morphism $ \flowerstar \colon \Ycal \to \Xcal $ is coherent if and only if $ \flowerstar^{\post} \colon \Ycal^{\post} \to \Xcal^{\post} $ is coherent if and only if $ \flowerstar^{\b} \colon \Ycal^{\b} \to \Xcal^{\b} $ is coherent \cite[3.4.13]{arXiv:1807.03281}
\end{recollection}

Some examples are in order.
The main one comes from sheaves on a finitary \site.

\begin{definition}\label{def:finitary_infty-site}
	\Asite $(\Ccal,\tau)$ is \defn{finitary} if $ \Ccal $ admits fiber products, and, for every object $ U \in \Ccal $ and every covering sieve $ S \subset \Ccal_{/U} $, there is a finite subset $\{U_i\}_{i\in I} \subset S $ that generates a covering sieve.
\end{definition}

\begin{proposition}[\SAG{Proposition}{A.3.1.3}]\label{prop:SAG.A.3.1.3}
	Let $(\Ccal,\tau)$ be a finitary \site.
	Then:
	\begin{enumerate}
		\item The \topos $\Sh_{\tau}(\Ccal)$ locally coherent.

		\item For every object $ U \in \Ccal $, the image of $ U $ under the sheafified Yoneda embedding is a coherent object of $\Sh_{\tau}(\Ccal)$.

		\item If, in addition, $ \Ccal $ admits a terminal object, then $ \Sh_{\tau}(\Ccal) $ is coherent.
	\end{enumerate}
\end{proposition}

\noindent Here are some more geometric examples that can be deduced from this.

\begin{example}
	If $ X $ is a sober topological space, then $ \Sh(X) $ is coherent if and only if $ X $ is spectral, i.e., additionally quasicompact, quasiseparated, and has a basis of quasicompact opens.
	In this case, $ \Sh(X)_{<\infty}^{\coh} $ is the full subcategory spanned by the constructible sheaves of anima on $ X $.
	If $ f \colon Y \to X $ is a map between spectral spaces, then the geometric morphism $ \flowerstar \colon \Sh(Y) \to \Sh(X) $ is coherent if and only if the map $ f $ is quasicompact.
\end{example}

\begin{example}
	A scheme $ X $ is quasicompact and quasiseparated if and only if its étale \topos $ X_{\et} $ is coherent.
	In this case, $ (X_{\et})_{<\infty}^{\coh} $ is the full subcategory spanned by the constructible étale sheaves of anima on $ X $.
	If $ f \colon Y \to X $ is any morphism between qcqs schemes, then the geometric morphism $ \flowerstar \colon Y_{\et} \to X_{\et} $ is coherent.
\end{example}

Let us now turn to explaining how \atopos that is both bounded and coherent is \emph{determined} by its truncated coherent objects.
The following is an axiomatization of the formal properties satisfied by the truncated coherent objects:

\begin{definition}[{(\pretopos)}]\label{def:pretopos}
	\Acategory $ \Ccal $ is an \defn{\pretopos} if:
	\begin{enumerate}
		\item The \category $ \Ccal $ admits finite limits.

		\item The \category $ \Ccal $ admits finite coproducts, which are universal and disjoint.

		\item Groupoid objects in $ \Ccal $ are effective, and their geometric realizations are universal.
	\end{enumerate}
	If $ \Ccal $ and $ \Dcal $ are \pretopoi, then a functor $ \fupperstar \colon \Ccal \to \Dcal $ is a \emph{morphism of \pretopoi} if $ \fupperstar $ preserves finite limits, finite coproducts, and effective epimorphisms.
\end{definition}

\begin{notation}
	We write $ \Pretop \subset \CATinfty $ for the subcategory consisting of \pretopoi and morphisms of \pretopoi.
	Given \pretopoi $ \Ccal $ and $ \Dcal $, we write
	\begin{equation*}
		\Funpre(\Ccal,\Dcal) \subset \Fun(\Ccal,\Dcal)
	\end{equation*}
	for the full subcategory spanned by the morphisms of \pretopoi.
\end{notation}

\begin{example}[{\SAG{Corollary}{A.6.1.7}}]
	Every \topos is \apretopos.
	If $\Xcal $ is a coherent \topos, then the full subcategory $ \Xcal^{\coh} \subset \Xcal $ spanned by the coherent objects is \apretopos.
\end{example}

\begin{definition}\label{def:boundedpretopos}
	\Apretopos $ \Ccal $ is \defn{bounded} if $ \Ccal $ is small and every object of $ \Ccal $ is truncated.
	We write
	\begin{equation*}
		\Pretopb \subset \Pretop
	\end{equation*}
	for the full subcategory spanned by the bounded \pretopoi.
\end{definition}

\begin{example}
	If $ \Xcal $ is a coherent \topos, then the full subcategory $ \Xcal\cohtrun $ is a bounded \pretopos.
\end{example}

In order to state the key classification theorem for bounded coherent \topoi, we need to fix some notation.
The first is for a natural Grothendieck topology on any \pretopos.

\begin{notation}[(effective epimorphism topology)]\label{ntn:effective_epimorphism_topology}
	Let $ \Ccal $ be \apretopos.
	We write $ \eff $ for the topology on $ \Ccal $ where a sieve $ S $ on $ X \in \Ccal $ is covering if and only if there exist finitely many object $ U_1,\ldots,U_n \in S $ such that the induced map $ U_1 \coproduct \cdots \coproduct U_n \to X $ is an effective epimorphism.
	This is a finitary topology that we refer to as the \defn{effective epimorphism topology} \cite[\SAGsubsec{A.6.2}]{SAG}.
	Importantly, the effective epimorphism topology on \apretopos is a subcanonical topology \SAG{Corollary}{A.6.2.6}.
\end{notation}

\begin{notation}\label{ntn:RTopcoh}
	We write $ \RTopcoh \subset \RTop $ for the subcategory whose objects are coherent \topoi and whose morphisms are coherent geometric morphisms.
	Given coherent \topoi $ \Xcal $ and $ \Ycal $, we write
	\begin{equation*}
		\Funupperstarcoh(\Xcal,\Ycal) \subset \Funupperstar(\Xcal,\Ycal)
	\end{equation*}
	for the full subcategory spanned by those algebraic morphisms $ \fupperstar \colon \Xcal \to \Ycal $ that preserve coherent objects, i.e., the \textit{coherent} algebraic morphisms.
	We write $ \RTopbc \subset \RTopcoh $ for the full subcategory spanned by those coherent \topoi that are also bounded.
\end{notation}

\begin{theorem}[{(classification of bounded coherent \topoi, \SAG{Theorem}{A.7.5.3})}]\label{thm:classification_of_bounded_coherent_topoi}
	The constructions
	\begin{equation*}
		\goesto{\Xcal}{\Xcal\cohtrun} \andeq \goesto{\Ccal}{\Sheff(\Ccal)}
	\end{equation*}
	are mutually inverse equivalences of \categories
	\begin{equation*}
		\RTopbc \simeq \Pretop^{\b,\op} \period
	\end{equation*}
	Moreover, for bounded coherent \topoi $ \Xcal $ and $ \Ycal $, restriction along the inclusion $ \Xcal\cohtrun \inclusion \Xcal $ defines an equivalence if \categories
	\begin{equation*}
		\Funupperstarcoh(\Xcal,\Ycal) \equivalence \Funpre(\Xcal\cohtrun,\Ycal\cohtrun) \period
	\end{equation*}
\end{theorem}

We conclude this subsection by collecting a few technical results that we could not find references for.
They're concerned with describing arbitrary algebraic morphisms from a coherent \topos in terms of truncated coherent objects, and the idempotent completeness of \categories of coherent algebraic morphisms.
First we record what happens in the bounded case:

\begin{proposition}\label{prop:algebraic_morphisms_from_a_bounded_coherent_topos_to_any_topos}
	Let $ \Xcal $ and $ \Ycal $ be \topoi.
	If $ \Xcal $ is bounded coherent, then restriction along the inclusion $ \Xcal\cohtrun \inclusion \Xcal $ defines an equivalence of \categories
	\begin{equation*}
		\Funupperstar(\Xcal,\Ycal) \equivalence \Funpre(\Xcal\cohtrun,\Ycal) \period
	\end{equation*}
\end{proposition}

\begin{proof}
	Since $ \Xcal $ is bounded coherent, by \Cref{thm:classification_of_bounded_coherent_topoi} we have $ \Xcal \equivalent \Sheff(\Xcal\cohtrun) $.
	Hence the claim follows from \SAG{Proposition}{A.6.4.4}. 
\end{proof}

\begin{lemma}\label{lem:coherent_objects_of_a_bounded_coherent_topos_are_closed_under_retracts}
	Let $ \Xcal $ be a bounded coherent \topos.
	Then the full subcategory $ \Xcal\cohtrun \subset \Xcal $ is closed under retracts.
	In particular, $ \Xcal\cohtrun $ is a small idempotent complete \category.
\end{lemma}

\begin{proof}
	See the proof of \SAG{Corollary}{A.7.5.4}.
\end{proof}

\begin{lemma}\label{lem:coherent_geometric_morphisms_are_closed_under_retracts}
	Let $ \Xcal $ and $ \Ycal $ be bounded coherent \topoi.
	Then the full subcategory
	\begin{equation*}
		\Funupperstarcoh(\Xcal,\Ycal) \subset \Funupperstar(\Xcal,\Ycal)
	\end{equation*}
	is closed under retracts.
	Hence, $ \Funupperstarcoh(\Xcal,\Ycal) $ is a small idempotent complete \category.
\end{lemma}

\begin{proof}
	By the classification of bounded coherent \topoi, 
	\begin{equation*}
		\Funupperstarcoh(\Xcal,\Ycal) \equivalent \Funpre(\Xcal\cohtrun,\Ycal\cohtrun) \period
	\end{equation*}
	Since both $ \Xcal\cohtrun $ and $ \Ycal\cohtrun $ are small \categories, $ \Funupperstarcoh(\Xcal,\Ycal) $ is also a small \category.

	For the statement about closure under retracts (which immediately implies idempotent completeness), let $ \fupperstar \colon \Xcal \to \Ycal $ be an algebraic morphism that is a retract in $ \Funupperstar(\Xcal,\Ycal) $ of an algebraic morphism $ \gupperstar \colon \Xcal \to \Ycal $ that preserves truncated coherent objects.
	Then for each truncated coherent object $ X \in \Xcal $, the object $ \fupperstar(X) $ is a retract of the truncated coherent object $ \gupperstar(X) $.
	\Cref{lem:coherent_objects_of_a_bounded_coherent_topos_are_closed_under_retracts} then implies that $ \fupperstar(X) $ is truncated coherent; that is $ \fupperstar $ preserves truncated coherent objects, as desired.
\end{proof}

For the condensed \categories of points considered in this note, we're interested in (coherent) geometric morphisms from an arbitrary coherent \topos to the \topos of sheaves on a profinite set. 
The latter is bounded and Postnikov complete.
In this situation, variants of \Cref{prop:algebraic_morphisms_from_a_bounded_coherent_topos_to_any_topos,lem:coherent_geometric_morphisms_are_closed_under_retracts} hold without the boundedness assumption on $ \Xcal $.

\begin{proposition}\label{prop:Funupperstar_to_a_bounded_Postnikov_complete_topos}
	Let $ \Xcal $ and $ \Ycal $ be \topoi.
	If $ \Ycal $ is bounded and Postnikov complete, then: 
	\begin{enumerate}
		\item\label{prop:Funupperstar_to_a_bounded_Postnikov_complete_topos.1} The natural geometric morphism $ \Xcal \to \Xcal^{\b} $ induces an equivalence
		\begin{equation*}
			\Funupperstar(\Xcal,\Ycal) \equivalence \Funupperstar(\Xcal^{\b},\Ycal) \period
		\end{equation*}

		\item\label{prop:Funupperstar_to_a_bounded_Postnikov_complete_topos.2} If $ \Xcal $ is coherent, then restriction along the inclusion $ \Xcal\cohtrun \inclusion \Xcal $ defines an equivalence of \categories
		\begin{equation*}
			\Funupperstar(\Xcal,\Ycal) \equivalence \Funpre(\Xcal\cohtrun,\Ycal) \period
		\end{equation*}

		\item\label{prop:Funupperstar_to_a_bounded_Postnikov_complete_topos.3} If $ \Xcal $ and $ \Ycal $ are coherent, then the natural geometric morphism $ \Xcal \to \Xcal^{\b} $ induces an equivalence
		\begin{equation*}
			\Funupperstarcoh(\Xcal,\Ycal) \equivalence \Funupperstarcoh(\Xcal^{\b},\Ycal) \period
		\end{equation*}
		Moreover, $ \Funupperstarcoh(\Xcal,\Ycal) $ is a small idempotent complete \category.
	\end{enumerate}
\end{proposition}

\begin{proof}
	For \eqref{prop:Funupperstar_to_a_bounded_Postnikov_complete_topos.1}, notice that since $ \Ycal $ is both bounded and Postnikov complete by \Cref{rec:Postnikov_completeness} we have natural equivalences
	\begin{align*}
		\Funupperstar(\Xcal,\Ycal) &\equivalent \Funupperstar(\Xcal^{\post},\Ycal) \\
		&\equivalent \Funupperstar((\Xcal^{\post})^{\b},\Ycal) \\
		&\equivalent \Funupperstar(\Xcal^{\b},\Ycal) \period
	\end{align*}

	For \eqref{prop:Funupperstar_to_a_bounded_Postnikov_complete_topos.2}, note that since the natural geometric morphism $ \Xcal \to \Xcal^{\b} $ restricts to an equivalence on truncated coherent objects, the claim follows from \eqref{prop:Funupperstar_to_a_bounded_Postnikov_complete_topos.1} and \Cref{prop:algebraic_morphisms_from_a_bounded_coherent_topos_to_any_topos}.
	Similarly, the equivalence in \eqref{prop:Funupperstar_to_a_bounded_Postnikov_complete_topos.3} follows from the fact that the natural geometric morphism $ \Xcal \to \Xcal^{\b} $ restricts to an equivalence on truncated coherent objects, item \eqref{prop:Funupperstar_to_a_bounded_Postnikov_complete_topos.2}, and \Cref{thm:classification_of_bounded_coherent_topoi}.
	The statement that $ \Funupperstarcoh(\Xcal,\Ycal) $ is small and idempotent complete then follows from \Cref{lem:coherent_geometric_morphisms_are_closed_under_retracts}.
\end{proof}

\subsection{Spectral \texorpdfstring{$\infty$}{∞}-topoi}\label{subsec:spectral_topoi}

We now briefly review the theory of \textit{spectral \topoi} introduced in our work with Barwick and Glasman \cite{arXiv:1807.03281}.
In addition to bounded coherence, spectrality asks for an additional condition on the \category of points of \atopos.

\begin{recollection}\label{rec:layered_categories}
	\Acategory $ \Ccal $ is \defn{layered} if for each object $ x \in \Ccal $, every endomorphism $ x \to x $ is an equivalence.
	Equivalently, $ \Ccal $ is layered if and only if there exists a poset $ P $ and a conservative functor $ \Ccal \to P $.
	We write $ \Lay \subset \Catinfty $ for the full subcategory spanned by the layered \categories.
\end{recollection}

\begin{recollection}[{(spectral \topoi)}]\label{rec:spectral_topoi}
	\Atopos $ \Xcal $ is \defn{spectral} if $ \Xcal $ is bounded coherent and the \category of points $ \Pt(\Xcal) $ is layered.
	If $ \Xcal $ is a spectral \topos, then every point of $ \Xcal $ is coherent.
	We write \smash{$ \RTopspec \subset \RTopcoh $} for the full subcategory spanned by the spectral \topoi.
\end{recollection}

\noindent Here's the most important example:

\begin{example}
	If $ X $ is a qcqs scheme, then the étale \topos of $ X $ is spectral.
\end{example}

One of the main results is that spectral \topoi admit an even more simple classification than bounded coherent \topoi, in terms of \textit{profinite} layered \categories.
Here's the correct notion of finiteness:

\begin{recollection}
	An anima $ X $ is \defn{\pifinite} if $ \uppi_0(X) $ is finite, $ X $ is truncated, and for each integer $ n \geq 1 $ and point $ x \in X $, the group $ \uppi_n(X,x) $ is finite.
	\Acategory $ \Ccal $ is \defn{\pifinite} if $ \Ccal $ has finitely many objects up to equivalence and all mapping anima are \pifinite.
	We write $ \Catfin \subset \Catinfty $ for the full subcategory spanned by the \pifinite \categories, and $ \Layfin \subset \Catfin $ for the full subcategory spanned by the \pifinite layered \categories. 
\end{recollection}

\begin{example}
	If $ \Ccal $ is a \pifinite layered \category, then there is a natural equivalence
	\begin{equation*}
		\Ccal \equivalence \Pt(\Fun(\Ccal,\An)) \period
	\end{equation*}
	Moreover, the \topos $ \Fun(\Ccal,\An) $ is spectral.
\end{example}

\begin{recollection}[{(\categorical Hochster duality)}]
	The assignment $ \Ccal \mapsto \Fun(\Ccal,\An) $ with functoriality given by right Kan extension defines a left exact functor
	\begin{equation*}
		\Layfin \to \RTopcoh \period
	\end{equation*}
	The \category $ \RTopcoh $ admits limits, so by the universal property of \proobjects, this functor extends to a limit-preserving functor
	\begin{equation}\label{eq:embedding_of_profinite_layered_categories_into_coherent_topoi}
		\Pro(\Layfin) \to \RTopcoh \period
	\end{equation}

ref_dict.ex:most_simple_examples_of_Ptbf:
\begin{example}\label{ex:most_simple_examples_of_Ptbf}
	Let $ \Xcal $ is the \topos of sheaves on the Sierpiński space.
	Then for each extremally disconnected profinite set $ K $, the inclusion \smash{$ \Ptcohbf(\Xcal)(K) \inclusion \Ptbf(\Xcal)(K) $} is simply the inclusion
	\begin{equation*}
		\Clopen(K) \inclusion \Open(K)
	\end{equation*}
	of the poset of clopen subsets of $ K $ into the poset of all open subsets.

	More generally, if $ X $ is a spectral topological space and $ \Xcal = \Sh(X) $, then $ \Ptbf(\Xcal)(K) $ is the poset $ \Map(K,X) $ of continuous maps $ K \to X $ ordered by \textit{pointwise specialization:} $ f \leq g $ if and only if for each $ k \in K $, we have \smash{$ f(k) \in \overline{\{g(k)\}} $}.
	In this case, \smash{$ \Ptcohbf(\Xcal)(K) $} is the subposet
	\begin{equation*}
		\Map^{\qc}(K,X) \subset \Map(K,X)
	\end{equation*}
	of \textit{quasicompact} maps, i.e., maps such that the preimage of a quasicompact open is clopen.
\end{example}

