\begin{corollary}\label{cor:restriction_from_PtXbetaS_to_PtXS_admits_a_right_adjoint}
	Let $ \Xcal $ be a coherent \topos and let $ S $ be a set.
	Then the restriction functor
	\begin{equation*}
		\begin{tikzcd}[sep=3.5em]
			\Funupperstar(\Xcal,\Sh(\upbeta(S))) \arrow[r, "\jupperstar \of -"] & \Funupperstar(\Xcal,\Sh(S)) \equivalent \Pt(\Xcal)^S 
		\end{tikzcd}
	\end{equation*}
	admits a fully faithful right adjoint.
\end{corollary}

