\begin{theorem}\label{thm:extra_adjoint_for_spectral_topoi}
	Let $ \Xcal $ be a spectral \topos.
	Then:
	\begin{enumerate}
		\item\label{thm:extra_adjoint_for_spectral_topoi.1} For each extremally disconnected profinite set $ K $, the inclusion \smash{$ \Ptcohbf(\Xcal)(K) \inclusion \Ptbf(\Xcal)(K) $} admits a left adjoint.

		\item\label{thm:extra_adjoint_for_spectral_topoi.2} The inclusion $ \Ptcohbf(\Xcal) \inclusion \Ptbf(\Xcal) $ induces an equivalence on condensed classifying anima.
