	Finally, \atopos $\Xcal $ is \defn{locally coherent} if every object $U\in \Xcal $ admits a cover $\{\fromto{V_i}{U}\}_{i\in I}$ in which each $V_i$ is coherent.
\end{definition}

post_theorem_intro_text:
\begin{warning}
	If $ \Xcal $ is a coherent \topos which is not spectral, then even the inclusion 
	\begin{equation*}
		\Ptcohbf(\Xcal)(\pt) \inclusion \Ptbf(\Xcal)(\pt)
	\end{equation*}
	of coherent points into all points need not admit a left adjoint.
	For example, if $ \Xcal $ is the classifying \topos of the theory of abelian groups, this is the inclusion of the subcategory of finite abelian groups into all abelian groups.
\end{warning}

We conclude the introduction by unpacking the two simplest cases of \Cref{intro_thm:extra_adjoint_for_spectral_topoi}.

\begin{nul}
	As in \Cref{ex:most_simple_examples_of_Ptbf}, first consider the case when $ \Xcal $ is the \topos of sheaves on the Sierpiński space.
	Then the statement is that the inclusion $ \Clopen(K) \inclusion \Open(K) $ admits a left adjoint.
	This is clear: it is given by sending $ U \subset K $ to the closure \smash{$ \overline{U} $} (which is open since $ K $ is extremally disconnected).
\end{nul}

\begin{nul}
	More generally, if $ \Xcal $ is the \topos of sheaves on a spectral topological space $ X $, then \Cref{intro_thm:extra_adjoint_for_spectral_topoi} says that the inclusion
	\begin{equation*}
		\Map^{\qc}(K,X) \inclusion \Map(K,X)
	\end{equation*}
	of the poset of quasicompact maps into all maps admits a left adjoint.
	That is, any map $ f \colon K \to X $ has a best approximation by a quasicompact map that is a pointwise generization of $ f $.

	In this case, we can demonstrate our method of proof of \Cref{intro_thm:extra_adjoint_for_spectral_topoi}.
	By the Stone duality equivalence between distributive lattices and spectral spaces, $ \Map^{\qc}(K,X) $ is isomorphic to the poset
	\begin{equation*}
		\Map_{\Latt}(\Open^{\qc}(X),\Clopen(K))
	\end{equation*}
	of lattice homomorphisms from the poset of quasicompact opens in $ X $ to the poset of clopens in $ K $.
	By the equivalence between sober spaces and frames, $ \Map(K,X) $ is isomorphic to the poset 
	\begin{equation*}
		\Map_{\Frame}(\Open(X),\Open(K))
	\end{equation*}
	of frame maps $ \Open(X) \to \Open(K) $.
	Since quasicompact opens form a basis for the topology on $ X $ and are closed under finite intersections, restriction defines an isomorphism of posets
	\begin{equation*}
		\Map_{\Frame}(\Open(X),\Open(K)) \equivalence \Map_{\Latt}(\Open^{\qc}(X),\Open(K)) \period
	\end{equation*}
	Here, the target consists of lattice homomorphisms $ \Open^{\qc}(X) \to \Open(K) $.
	Under these identifications, the inclusion $ \Map^{\qc}(K,X) \inclusion \Map(K,X) $ is identified with the obvious inclusion
	\begin{equation}\label{eq:inclusion_of_lattice_maps}
		\Map_{\Latt}(\Open^{\qc}(X),\Clopen(K)) \inclusion \Map_{\Latt}(\Open^{\qc}(X),\Open(K)) \period
	\end{equation}
	To see that this admits a left adjoint, note that, again since $ K $ is extremally disconnected, the closure operator $ \Open(K) \to \Clopen(K) $ is left adjoint to the inclusion, and also preserves finite joins and the initial object.
	In an extremally disconnected space, for open subsets $ U $ and $ V $, we also have the identity $ \overline{U \intersect V} = \overline{U} \intersect \overline{V} $.
	Hence pointwise application of the closure operator $ \Open(K) \to \Clopen(K) $ defines a left adjoint to the inclusion \eqref{eq:inclusion_of_lattice_maps}.
\end{nul}

\subsection{Linear overview}

In \cref{sec:around_the_Los_ultraproduct_theorem}, we explain a sheaf-theoretic interpretation of the Łoś ultraproduct theorem.
This is implicit in Lurie's work on ultracategories \cite{Ultracategories}, and is what lets us analyze the condensed classifying anima of the condensed \category of points $ \Ptbf(\Xcal) $.
In \cref{sec:classifying_anima_of_condensed_categories_of_points}, we introduce the condensed \categories of points we consider in full detail, and prove \Cref{intro_thm:extra_adjoint_for_spectral_topoi}.
Since the results require a number of technical notions from the theory of \topoi, in \Cref{app:complements_on_topoi}, we've collected background on bounded and Postnikov complete \topoi, coherent \topoi and the classification of bounded coherent \topoi in terms of \pretopoi, and spectral \topoi.

\subsection{Notational conventions}

\begin{enumerate}
	\item We write $ \CATinfty $ for the \category of large \categories, and $ \AN \subset \CATinfty $ for the full subcategory spanned by the large anima (also referred to as spaces or \groupoids).
	We write $ \Catinfty \subset \CATinfty $ and $ \An \subset \AN $ for the full subcategories spanned by the small \categories and anima, respectively.

	\item We write $ \RTop $ for the \category of \topoi and geometric morphisms, i.e., right adjoints $ \flowerstar $ whose left adjoint $ \fupperstar $ is left exact.

	\item Given \categories $ \Xcal $ and $ \Ycal $ with limits and colimits, we write
	\begin{equation*}
		\Funlowerstar(\Ycal,\Xcal) \subset \Fun(\Ycal,\Xcal)
	\end{equation*}
	for the full subcategory spanned by the right adjoint functors whose left adjoint is left exact (when $ \Xcal $ and $ \Ycal $ are \topoi these are the geometric morphisms of \topoi).
	We write
	\begin{equation*}
		\Funupperstar(\Xcal,\Ycal) \subset \Fun(\Xcal,\Ycal)
	\end{equation*}
	for the full subcategory spanned by the left exact left adjoints (when $ \Xcal $ and $ \Ycal $ are \topoi these are the \defn{algebraic} morphisms of \topoi).

	\item Given \atopos $ \Xcal $ we write $ \Pt(\Xcal) \colonequals \Funupperstar(\Xcal,\An) $ for the \textit{\category of points} of $ \Xcal $.

	\item If $ \Xcal $ and $ \Ycal $ are \textit{coherent} \topoi (see \Cref{rec:coherence}), we write $ \Funupperstarcoh(\Xcal,\Ycal) \subset \Funupperstar(\Xcal,\Ycal)  $ for the full subcategory spanned by those left exact left adjoints that also preserve coherent objects. 

	\item Given \pretopoi $ \Ccal $ and $ \Dcal $ (see \Cref{def:pretopos}), we write $ \Funpre(\Ccal,\Dcal) \subset \Fun(\Ccal,\Dcal) $ for the full subcategory spanned by the morphisms of \pretopoi.
	That is, the functors that preserve finite limits, finite coproducts, and effective epimorphisms.
\end{enumerate}

\subsection{Acknowledgments}

We thank Clark Barwick for countless insightful conversations over the years around many of the topics appearing in this note.  
We thank Jacob Lurie for enlightening discussions on his work on ultracategories; in particular, for indicating that \Cref{cor:restriction_from_PtXbetaS_to_PtXS_admits_a_right_adjoint} should be true.

