ref_dict.asy:
\begin{proof}

First, we will consider the totally real case. Let $K$ be a totally real number field. It follows from  Lemma \ref{conductoroffreycurve} that $E$ is semistable outside the primes dividing $2C$. Moreover, $\overline{\rho}_{E,p}$ is irreducible by Corollary~\ref{galrepsurjective}, and $E$ is modular by Proposition~\ref{modularityoffreycurveovertotallyreal} after taking $V$  sufficiently large. We then apply Theorem \ref{level lowering} (after enlarging $V$ to ensure that $\mathbb{Q}(\zeta_p)^+ \nsubseteq K$) and Lemma \ref{conductoroffreycurve} to obtain  $\overline{\rho}_{E,p}\sim \overline{\rho}_{\mathfrak{f},\varpi}$ for some Hilbert newform  $\frakf$ of level $\mathcal{N}_p$ and some prime $\varpi\mid p$ of $\Q_{\mathfrak{f}}$ where $\Q_\frakf$ denotes the field generated by the Hecke eigenvalues of $\frakf$. 

\vspace{1.5mm}

Now we reduce to the case where $\Q_{\mathfrak{f}}=\mathbb{Q}$ to apply Theorem \ref{thm:ES}, after possibly enlarging $V$ by an effective amount. This step uses standard ideas originally due to Mazur that can be found in \cite[Section 4]{bs04} and  \cite[Proposition 15.4.2]{cohen07}.  Next, we want to show that there is some elliptic curve $E'/K$ of conductor $\mathcal{N}_p$ having the same $L$-function as $\mathfrak{f}$.  We know that $E$ has potentially multiplicative reduction at $\widetilde\frakP$ and $p\mid \# \overline{\rho}_{E,p}(I_{\widetilde\frakP})$ by Lemma \ref{potmultred}.  We can conclude that there is an elliptic curve $E'=E_\frakf$ of conductor $\calN_p$ satisfying $\overline{\rho}_{E,p} \sim \overline{\rho}_{E',p}$ if we implement Theorem \ref{thm:ES} after possibly enlarging $V$ to ensure that $p \nmid (\Norm_{K/\mathbb{Q}}(\widetilde{\mathfrak{P}})\pm 1)$.

\vspace{1.5mm}

    In the general case, $K$ is not necessarily totally real. For $p$ large enough, Lemma \ref{eichlershimura} implies that we have an elliptic curve $E'/K$ of conductor $\frakN'$ dividing $\frakN_E$ such that $\overline{\rho}_{E,p}\sim \overline{\rho}_{E',p}$, which completes (i) and (ii) as $\frakN_E$ is supported on $S_K$ by Lemma~\ref{conductoroffreycurve}. 

\vspace{1.5mm}

Now, suppose that $E'$ is $2$-isogenous to an elliptic curve $E''$. As the isogeny induces
an isomorphism $E'[p] \equiv E''[p]$ of Galois modules ($p\neq 2$), we get $\overline{\rho}_{E,p}\sim \overline{\rho}_{E',p}\sim\overline{\rho}_{E'',p}$ completing the proof of (ii). After possibly replacing $E'$ by $E''$, we can suppose that $E'$ has a $K$-rational point of order $2$ giving us (iii).

    \vspace{1.5mm}

    It remains to prove  $v_{\widetilde\frakP}(j')<0$ where $j'$ is the $j$-invariant of $E'$. By Lemma~\ref{potmultred}, the prime $p$ divides the size of $\overline{\rho}_{E,p}(I_{\widetilde\frakP})$. 
	It now follows from Lemma~\ref{imageofinertia} that $v_{\widetilde\frakP}(j')<0$ since the sizes of  
	$\overline{\rho}_{E,p}(I_{\widetilde\frakP})$ and $\overline{\rho}_{E',p}(I_{\widetilde\frakP})$ are equal.
\end{proof}

\section{Asymptotic Results}\label{asy}

Before going into the details of the proof, we will state the relationship between solutions of $S$-unit equations and certain families of elliptic curves. 

\begin{lemma}\label{lmm:bijection}
    Let $K$ be a number field and $E/K$ be an elliptic curve with a $K$-rational point of order $2$. Then $E$ has a model of the form
    \begin{equation*}
        E: Y^2=X^3+aX^2+bX.
    \end{equation*}
    Further, there is a bijection between
    \begin{equation*}
        \{E/K \text{ with a } K \text{-torsion of order } 2 \text{ up to } \Kbar \text{-isomorphism} \} \longrightarrow \P^1(K)-\{4,\infty\}
    \end{equation*}
    via the map $E\mapsto \lambda:=\frac{a^2}{b}$.
\end{lemma}
\begin{proof}
This is \cite[Lemma 15 (i)]{moc22}.
\end{proof}

ref_dict.level:
\begin{remark}
   Given a number field $K$, we obtain a \emph{complex conjugation} for every real embedding 
$\sigma: K \hookrightarrow \mathbb R$ and every extension $\widetilde{\sigma}: \overline{K} \hookrightarrow \mathbb C$ of 
$\sigma$ as $\widetilde{\sigma}^{-1}\iota \widetilde{\sigma} \in G_K$ where $\iota$ is the usual complex conjugation. Recall that a representation $\overline{\rho}: G_K \rightarrow \GL_2(\overline{\mathbb F}_p)$ is \emph{odd} if the determinant of every complex  conjugation is $-1$.  If the number field $K$ has no real embeddings, then we immediately say that $\overline{\rho}$ is odd. It follows from Lemma \ref{conductoroffreycurve} that $\overline{\rho}_{E,p}$ is odd.

\end{remark}

\section{Properties of Galois Representations and Level Lowering} \label{level}

In this section, we first prove the irreducibility of the mod $p$ Galois
representation, $\overline{\rho}_{E,p}$, associated to the Frey elliptic curve and then we relate it with another representation of lower level via a new elliptic curve $E'$ whose conductor is independent of the solution.

\subsection{Irreducibility of the associated Galois representation $\overline{\rho}_{E,p}$}

We need to prove the irreducibility of the mod $p$ Galois
representation associated to the Frey elliptic curve. This is needed in the level lowering step, which will be proved in Section \ref{ES}.
The following well-known result about subgroups of $\GL_2(\mathbb F_p)$ will be used to prove the irreducibility of the Galois representation $\overline{\rho}_{E,p}$.

\begin{theorem}\label{subgroups} Let $E$ be an  elliptic curve over a number field $K$ of degree $d$ and let $G \leq \GL_2(\mathbb F_p)$ be the
	image of the mod $p$ Galois representation $\overline{\rho}_{E,p}$ of $E$.
	Then the following holds:
	\begin{itemize}
		\item If $p \mid  \#G$ then either $\overline{\rho}_{E,p}$ is reducible or $G$ contains ${\rm SL}_2(\mathbb F_p)$. In the latter case, we deduce that $\overline{\rho}_{E,p}$ is absolutely irreducible. 
		\item If $p \nmid \#G$ and $p > 15 d +1$ then $G$ is contained in a Cartan subgroup or $G$ is contained in the normalizer of a Cartan subgroup but not the Cartan subgroup itself.

	\end{itemize}
\end{theorem}
\begin{proof}
	For the proof, the main reference is \cite[Lemma 2]{SD}. The version above including the proof of the second part is from \cite[Propositions 2.3  and 2.6]{localglobal}.
\end{proof}

The following is Proposition 6.1 from \c{S}eng\"{u}n and Siksek \cite{SS}. We include its statement for the convenience of the reader but we will omit its proof and refer to \cite{SS} instead.

\vspace{1.5mm}

\begin{prop}\label{irredpp3}
	Let $L$ be a Galois number field and let $\frakq$ be a prime of $L$. There is a constant $B_{L,\frakq}$ such that the following is true. Let $p > B_{L, \frakq}$ be  a rational prime. Let $E/L$ be an elliptic curve that is semistable at all $\frakp \mid  p$ and has potentially multiplicative reduction at $\frakq$. Then $\overline{\rho}_{E,p}$ is irreducible. 	
\end{prop}

We apply this  to our Frey curve given in \eqref{Frey} to obtain the surjectivity of  $\overline{\rho}_{E,p}$.
\begin{cor}\label{galrepsurjective}
	Let $K$ be a number field, and fix $\widetilde\frakP\in T_{K}$.  There is a constant $D=D(A,B,C,K)$ such that if $p>D$ and 
	$(a,b,c)$ is a non-trivial primitive solution to \eqref{maineqn} with $\widetilde\frakP\mid b$, then  the Galois representation $\overline{\rho}_{E,p}$ is surjective.
\end{cor}
\begin{proof} It follows by Lemma \ref{potmultred} that if $p>6v_{\widetilde\frakP}(2)$, the Frey curve $E$ has potentially multiplicative reduction at $\widetilde\frakP$.  Also, $E$ is semistable away from the primes dividing $2C$ by Lemma \ref{conductoroffreycurve}.  Let $L$ be the Galois closure of $K$, and let $\widetilde\frakq$ be a prime	of $L$ above $\widetilde\frakP$. Now, by applying Proposition \ref{irredpp3}, we get a constant $B_{L,\widetilde\frakq}$ such that $\overline{\rho}_{E,p}$ is irreducible whenever $p>B_{L,\widetilde\frakq}$. Note that there are only finitely many choices of $\widetilde\frakq$ in $L$ dividing $\widetilde\frakP$, and $L$ only depends on $K$.  Hence, we can obtain a constant depending only on $A,B,C, K$ and we denote it by $D=D(A,B,C,K)$. 	We also enlarge $D$, if necessary, so that $D>6v_{\widetilde\frakP}(2)$ (since we applied Lemma~\ref{potmultred}) and deduce that $\overline{\rho}_{E,p}$ is irreducible when $p>D$ by Proposition \ref{irredpp3}.

    \vspace{1.5mm}

    Now, we apply Lemma \ref{potmultred} again and see that the image of $\overline{\rho}_{E,p}$ contains an element of order $p$.  By Theorem \ref{subgroups} any subgroup of $\GL_2(\F_p)$ 
	having an element of order $p$ is either reducible or contains ${\rm SL}_2(\F_p)$. As $p>D>6v_{\frakP}(2)$, which implies that $\overline{\rho}_{E,p}$ is irreducible, the image	contains ${\rm SL}_2(\F_p)$.  Finally, we can ensure that $K\cap\Q(\zeta_p)=\Q$ by taking $D$ large enough if needed.	Hence, $\chi_p=\det(\overline{\rho}_{E,p})$ is surjective giving the following short exact sequence  \begin{equation*}
     1 \longrightarrow \SL_2(\F_p) \longrightarrow \overline{\rho}_{E,p}(G_K) \xrightarrow{\;\;\det\;\;} \F_p^\times \longrightarrow 1,
 \end{equation*}
 which completes the proof.
\end{proof}

\subsection{Level Lowering and Eichler-Shimura}
\label{ES}

For our asymptotic results, namely for Theorems \ref{maintheoremA}, \ref{maintheoremB} and \ref{maintheoremC}, we will need to relate the Galois representation $\overline{\rho}_{E,p}$ attached to the Frey curve $E$ with another representation of lower level via a new elliptic curve $E'$ whose conductor is independent of the solution.  We will use $E'$ to arrive at a contradiction in our asymptotic result.  The rest of this section is devoted to proving Theorem \ref{levellowerinandeichlershimura} which gives the properties of $E'$. The key ideas of the aforementioned theorem depend on the so-called Level-Lowering Theorem (Theorem \ref{level lowering}) and Eichler-Shimura Theorem (Theorem \ref{thm:ES}) when the field $K$ is totally real.

\subsubsection{Totally real case}\label{eichlershimuratotallyrealcase} We present a level-lowering result, which can be viewed as a generalization of Ribet's Level Lowering Theorem, by Freitas and Siksek \cite[Theorem 7]{FSANT} derived from the work of Fujira, Jarvis, and Rajaei.
For an elliptic curve $E/K$ of conductor $\calN_E$, we recall the definition of $\calN_p$ :

\begin{equation}
    \calN_p:=\calN_E\bigg/ {\displaystyle\prod_{\substack{\frakq\mid \mid \calN_E\\p\mid v_\frakq(\Delta_\frakq)}}}\frakq,
\end{equation}
where $p$ be a rational prime and $\Delta_\frakq$ is the discriminant of a local minimal model for $E$ at $\frakq$.
\begin{theorem} (Level-Lowering)\label{level lowering}
 	Let $K$ be a totally real number field and $E/K$ an elliptic curve of conductor $\calN_E$. Let $p$ be a rational prime. For a prime $\frakq$ of $K$, let $\Delta_\frakq$ denote the minimal discriminant of $E$ at $\frakq$, and $\calN_p$ be as in \eqref{reducedconductor}.  Suppose that the following statements hold:
 	\begin{enumerate}[(i)]
 		\item $p\geq 5$, the ramification index $e(\mathfrak{q}/p)<p-1$ for all $\mathfrak{q}\mid p$, and $\mathbb{Q}(\zeta_p)^+ \nsubseteq K$,
 		\item $E$ is modular,
 		\item $\overline{\rho}_{E,p}$ is irreducible,
 		\item $E$ is semistable at all $\mathfrak{q}\mid p$,
 		\item $p\mid v_{\mathfrak{q}}(\Delta_{\mathfrak{q}})$ for all $\mathfrak{q}\mid p$.
 	\end{enumerate}
 	Then there is a Hilbert eigenform $\mathfrak{f}$ of parallel weight two that is new at level $\mathcal{N}_p$ and some prime $\varpi$ of $\Q_{\mathfrak{f}}$ such that $\varpi\mid p$ and 
 	$\overline{\rho}_{E,p} \sim \overline{\rho}_{\mathfrak{f},\varpi}$.
 \end{theorem}

  Eichler-Shimura conjecture, which can be viewed as a converse of the modularity, states that for a Hilbert newform $\frakf$ of level $\calN$ and parallel weight two with rational eigenvalues, there is an elliptic curve $E_\frakf /K$ with conductor $\calN$  having the same $L$-function as $\frakf$. Below, we try to summarize some of the cases in which the conjecture holds true. 

\begin{theorem} \label{thm:ES}
	Let $K$ be a totally real field and let $\frakf$  be a Hilbert
	newform over $K$ of level $\mathcal N$ and parallel weight $2$, such that $\Q_\frakf = \Q$. 

	\begin{enumerate}
		\item If the degree of $K$ over $\Q$ is odd then there is an elliptic curve $E_\frakf/K$ of conductor $\mathcal N$ with the same $L$-function as $\frakf$. (Blasius \cite{Blas04}, Hida \cite{Hida})

		\item Let $p$ be an odd prime and $\frakq\nmid p$ be a prime of $K$.  Suppose $\bar{\rho}_{E,p}$ is irreducible, and $\bar{\rho}_{E,p} \sim \bar{\rho}_{\frakf,p}$ with the following properties:
		\begin{enumerate}
			\item $E$ has potentially multiplicative reduction at $\frakq$,
			\item $p \mid  \# \bar{\rho}_{E,p}(I_\frakq) $ where $I_\frakq$ denotes the inertia group at $p$,
			\item $p \nmid (\text{Norm}_{K/\Q}(\frakq) \pm 1)$,
		\end{enumerate}
		then there is an elliptic curve $E_\frakf/K$ of conductor $\mathcal N$ with the same $L$-function as $\frakf$. (Freitas-Siksek Corollary 2.2 in \cite{FS})
	\end{enumerate}
\end{theorem}

\subsubsection{General case} 

Now, we apply Conjecture~\ref{conj1} to relate the residual representation $\overline{\rho}_{E,p}$ to a weight two, mod $p$ eigenform $\theta$ over $K$ of level $\frakN_E$. One of the main steps toward the proof is to lift mod $p$ eigenforms to complex ones. The following result is due to \c{S}eng\"{u}n and Siksek.

\begin{prop}[\cite{SS}, Proposition 2.1]\label{eigenform}
	Let $\frakN$ be an ideal of $\calO_K$ .There is an integer $B(\frakN)$ depending only on $\frakN$ such that for any prime $p>B(\frakN)$, every weight two, mod $p$ eigenform of level $\frakN$ lifts to a complex one.
\end{prop}

In addition to Conjecture~\ref{conj1}, we will use a special case of a fundamental conjecture from the Langlands Programme since not everything is known about the connection between eigenforms and elliptic curves over general number fields. Recall that a simple abelian surface $A$ over $K$ whose algebra $\End_K(A)\otimes_{\Z}\Q$ of $K$-endomorphisms is an indefinite division quaternion algebra $D$ over $\Q$ is called a \textit{fake elliptic curve} (see \cite[\S 4]{SS}).

\begin{conj}[\cite{SS}, Conjecture 4.1]\label{conj2}
	Let $\frakf$ be a weight two complex eigenform over $K$ of level $\frakN$ that is non-trivial and new.  If $K$ has some
	real place, then there exists an elliptic curve $E_{\frakf}/K$ of conductor $\frakN$ such that 
	\begin{equation}\label{c2eqn}
		\#E_{\frakf}(\O_K/\frakq)=1+\Norm(\frakq)-\frakf(T_{\frakq})\quad\mbox{for all}\quad\frakq\;\nmid\;\frakN.
	\end{equation}
	If $K$ is totally complex, then there exists either an elliptic curve $E_{\frakf}$ of conductor $\frakN$ satisfying (\ref{c2eqn})
	or a fake elliptic curve 
	$A_{\frakf}/K$, of conductor $\frakN^2$, such that
	\begin{equation}
		\#A_{\frakf}(\O_K/\frakq)=(1+\Norm(\frakq)-\frakf(T_{\frakq}))^2\quad\mbox{for all}\quad\frakq\;\nmid\;\frakN.
	\end{equation}
\end{conj}	

\vspace{1.5mm}

Let $K$ be a number field which is not totally real and assume Conjecture~\ref{conj1} and Conjecture~\ref{conj2} hold for $K$. Under these assumptions, we prove the following lemma which is an important step in the proof of Theorem \ref{levellowerinandeichlershimura}.

\begin{lemma}\label{eichlershimura}
	There is a non-trivial, new (weight two) complex eigenform $\frakf$ which has an associated elliptic curve  $E_{\frakf}/K$ of conductor $\frakN'$ dividing $\frakN_E$.
\end{lemma}
\begin{proof}
     We first show the existence of such an eigenform $\frakf$ of level $\frakN_E$. By Corollary \ref{galrepsurjective}, we see that the representation $\overline{\rho}_{E,p}:G_K\rightarrow \GL_{2}(\mathbb{F}_p) $ is surjective, hence is absolutely irreducible for $p>D=D(A, B, C, K)$.  Now, we apply  Conjecture \ref{conj1} to deduce that there is 
	a weight two mod $p$ eigenform $\theta$ over $K$ of level $\frakN_E$, with $\frakN_E$ as in Lemma \ref{conductoroffreycurve}, such that for all primes $\frakq$ coprime to $p\frakN_E$, we have 	\[\tr(\overline{\rho}_{E,p}({\rm Frob}_{\frakq}))=\theta(T_{\frakq}).\]

We also know from the same lemma that there are only finitely many possible levels $\frakN_E$.  Thus, by taking $p$
	large enough, see Proposition \ref{eigenform}, for any level $\frakN_E$
	there is a weight two complex eigenform $\frakf$ of level $\frakN_E$ which is a lift of $\theta$. Note that since there are only finitely many such eigenforms $\frakf$
	and they depend only on $K,A,B,C$, from now on we can suppose that every constant depending on these eigenforms depends
	only on $K,A,B,C$.

 \vspace{1.5mm}

 Next, following exactly the same steps as in \cite[Lemma 7.2]{SS} we can see that if $\Q_\frakf\neq\Q$ then  there is a constant $C_{\frakf}$ depending only on $\frakf$ such that 
	$p<C_{\frakf}$.  Therefore, by taking $p$ sufficiently large, we assume that $\Q_\frakf=\Q$. 
	In order to apply Conjecture \ref{conj2}, we need to
	show that $\frakf$ is non-trivial and new.  As $\overline{\rho}_{E,p}$ is irreducible, the eigenform $\frakf$ is non-trivial.  
	If $\frakf$ is new, we are done.  If not, we can replace it with an equivalent new eigenform of a smaller level.  Therefore,
	we can take $\frakf$ new with level $\frakN'$ dividing $\frakN_E$.
	Finally, we apply Conjecture \ref{conj2} and obtain that $\frakf$ either has an associated elliptic curve $E_{\frakf}/K$ of conductor $\frakN'$, or has an associated fake elliptic curve $A_{\frakf}/K$ of conductor $\frakN'^2$.

 \vspace{1.5mm}

	By Lemma \ref{fakeellipticcurve} below, if $p>24$, then $\frakf$ has an associated elliptic curve $E_{\frakf}$. As a result, we can assume that $\overline{\rho}_{E,p}\sim \overline{\rho}_{E',p}$ where $E'=E_{\frakf}$ is an elliptic curve with conductor $\frakN'$ dividing $\frakN_E$.  

\end{proof}

\begin{lemma}\cite[Lemma 7.3]{SS}\label{fakeellipticcurve}
	If $p>24$, then $\frakf$ has an associated elliptic curve $E_{\frakf}$.
\end{lemma}

The following lemma will allow us to take $p$ large enough so that $E'$ has a $K$-rational point
of order $2$.
  \begin{lemma}\label{full2torsion}
  If $E'$ does not have a nontrivial $K$-rational point of order $2$, and is not isogenous to an elliptic curve with a nontrivial $K$-rational point of order $2$, then $p<C_{E'}$ where $C_{E'}$ is a constant depending only on $E'$. 
		\end{lemma}
  \begin{proof}
         By \cite[Theorem 2]{Katz81} there are infinitely many primes $\frakq$ such that $\# E'(\F_\frakq)\not \equiv 0 \pmod 2$.  Fix such a prime $\frakq\not\in S_K$ and note that $E$ is semistable at $\frakq$.  If $E$ has good reduction at $\frakq$, then $\# E(\F_\frakq)\equiv \# E'(\F_\frakq) \pmod p$. Since $\# E(\F_\frakq)$ is divisible by $2$, the difference $\# E(\F_\frakq)- \# E'(\F_\frakq)$, which is divisible by $p$, is nonzero.  As the difference belongs to a finite set depending on $\frakq$, the rational prime $p$ becomes bounded.  If $E$ has multiplicative reduction at $\frakq$, we obtain 
      \[
		\pm(\Norm(\frakq)+1)\equiv a_{\frakq}(E') \pmod p
		\]
		by comparing the traces of Frobenius.  We see that this difference being also nonzero and depending only on $\frakq$ gives a bound for $p$.
  \end{proof}

Now, we state and prove the main theorem of this section.

   \begin{theorem}\label{levellowerinandeichlershimura}
Let $K$ be a number field, and let $\widetilde\frakP\in T_{K}$ be a fixed prime. If $K$ is not totally real, we assume both Conjecture~\ref{conj1} and Conjecture~\ref{conj2} hold for $K$. There is a constant $V=V(A, B, C, K)$ depending only on $K$ and $A,B,C$ such that, for $p>V$, the following holds: 
Let $(a,b,c)$ be a putative solution to \eqref{maineqn} with $\widetilde\frakP\mid b$. Write $E$ for the Frey curve in \eqref{Frey}.
Then there is an elliptic curve $E'$ over $K$ such that:
\begin{enumerate}[(i)]
\item the elliptic curve $E'$ has good reduction away from $S_K$;
\item $\overline{\rho}_{E,p} \sim \overline{\rho}_{E',p}$;
\item $E'$ has a $K$-rational point of order $2$;
\item for $\widetilde\frakP\in T_{K}$, $v_{\widetilde\frakP}(j_{E'})<0$ where $j_{E'}$ is the $j$-invariant of $E'$.
\end{enumerate}
\end{theorem}  
\begin{proof}

First, we will consider the totally real case. Let $K$ be a totally real number field. It follows from  Lemma \ref{conductoroffreycurve} that $E$ is semistable outside the primes dividing $2C$. Moreover, $\overline{\rho}_{E,p}$ is irreducible by Corollary~\ref{galrepsurjective}, and $E$ is modular by Proposition~\ref{modularityoffreycurveovertotallyreal} after taking $V$  sufficiently large. We then apply Theorem \ref{level lowering} (after enlarging $V$ to ensure that $\mathbb{Q}(\zeta_p)^+ \nsubseteq K$) and Lemma \ref{conductoroffreycurve} to obtain  $\overline{\rho}_{E,p}\sim \overline{\rho}_{\mathfrak{f},\varpi}$ for some Hilbert newform  $\frakf$ of level $\mathcal{N}_p$ and some prime $\varpi\mid p$ of $\Q_{\mathfrak{f}}$ where $\Q_\frakf$ denotes the field generated by the Hecke eigenvalues of $\frakf$. 

\vspace{1.5mm}

Now we reduce to the case where $\Q_{\mathfrak{f}}=\mathbb{Q}$ to apply Theorem \ref{thm:ES}, after possibly enlarging $V$ by an effective amount. This step uses standard ideas originally due to Mazur that can be found in \cite[Section 4]{bs04} and  \cite[Proposition 15.4.2]{cohen07}.  Next, we want to show that there is some elliptic curve $E'/K$ of conductor $\mathcal{N}_p$ having the same $L$-function as $\mathfrak{f}$.  We know that $E$ has potentially multiplicative reduction at $\widetilde\frakP$ and $p\mid \# \overline{\rho}_{E,p}(I_{\widetilde\frakP})$ by Lemma \ref{potmultred}.  We can conclude that there is an elliptic curve $E'=E_\frakf$ of conductor $\calN_p$ satisfying $\overline{\rho}_{E,p} \sim \overline{\rho}_{E',p}$ if we implement Theorem \ref{thm:ES} after possibly enlarging $V$ to ensure that $p \nmid (\Norm_{K/\mathbb{Q}}(\widetilde{\mathfrak{P}})\pm 1)$.

\vspace{1.5mm}

    In the general case, $K$ is not necessarily totally real. For $p$ large enough, Lemma \ref{eichlershimura} implies that we have an elliptic curve $E'/K$ of conductor $\frakN'$ dividing $\frakN_E$ such that $\overline{\rho}_{E,p}\sim \overline{\rho}_{E',p}$, which completes (i) and (ii) as $\frakN_E$ is supported on $S_K$ by Lemma~\ref{conductoroffreycurve}. 

\vspace{1.5mm}

Now, suppose that $E'$ is $2$-isogenous to an elliptic curve $E''$. As the isogeny induces
an isomorphism $E'[p] \equiv E''[p]$ of Galois modules ($p\neq 2$), we get $\overline{\rho}_{E,p}\sim \overline{\rho}_{E',p}\sim\overline{\rho}_{E'',p}$ completing the proof of (ii). After possibly replacing $E'$ by $E''$, we can suppose that $E'$ has a $K$-rational point of order $2$ giving us (iii).

    \vspace{1.5mm}

    It remains to prove  $v_{\widetilde\frakP}(j')<0$ where $j'$ is the $j$-invariant of $E'$. By Lemma~\ref{potmultred}, the prime $p$ divides the size of $\overline{\rho}_{E,p}(I_{\widetilde\frakP})$. 
	It now follows from Lemma~\ref{imageofinertia} that $v_{\widetilde\frakP}(j')<0$ since the sizes of  
	$\overline{\rho}_{E,p}(I_{\widetilde\frakP})$ and $\overline{\rho}_{E',p}(I_{\widetilde\frakP})$ are equal.
\end{proof}

\section{Asymptotic Results}\label{asy}

Before going into the details of the proof, we will state the relationship between solutions of $S$-unit equations and certain families of elliptic curves. 

\begin{lemma}\label{lmm:bijection}
    Let $K$ be a number field and $E/K$ be an elliptic curve with a $K$-rational point of order $2$. Then $E$ has a model of the form
    \begin{equation*}
        E: Y^2=X^3+aX^2+bX.
    \end{equation*}
    Further, there is a bijection between
    \begin{equation*}
        \{E/K \text{ with a } K \text{-torsion of order } 2 \text{ up to } \Kbar \text{-isomorphism} \} \longrightarrow \P^1(K)-\{4,\infty\}
    \end{equation*}
    via the map $E\mapsto \lambda:=\frac{a^2}{b}$.
\end{lemma}
\begin{proof}
This is \cite[Lemma 15 (i)]{moc22}.
\end{proof}

Let $S$ be a finite set of primes of $\O_K$ and let $\O_S$ be the ring of $S$-integers and $\mathcal{O}_{S}^\times$ be the group of $S$-units.

\begin{lemma}\label{lmm:bijection2}
    Let $K$ be a number field and $S$ be a set of finite primes of $K$. If $S$ contains the primes above $2$, we then have the following bijection
    \begin{equation*}
       \left \{\displaystyle{\substack{E/K \text{ with a } K \text{-torsion of order } 2 \text{ with potentially } \\
       \text{good reduction outside } S\text{ up to } \Kbar \text{-isomorphism}}} \right\} \longrightarrow \mathcal{O}_{S}^\times
    \end{equation*}
    via the map $E\mapsto \mu:=\lambda-4\in\mathcal{O}_{S}^\times $, where $\lambda$ is given as in Lemma \ref{lmm:bijection}.
\end{lemma}
\begin{proof}
This is \cite[Lemma 16 (i)]{moc22}.
\end{proof}

\begin{lemma}\label{lmm:fractionalideal}
 Let $K$ be a number field and $S$ be a set of finite primes of $K$. Let $E/K$ be an elliptic curve
with good reduction outside $S$. Suppose $S$ contains the primes above $2$ and $E$ has a $K$-torsion point of order 2. Let $(\lambda,\mu) \in \O_S \times \mathcal{O}_{S}^\times$ correspond to $E$ as in Lemma \ref{lmm:bijection2} and therefore satisfies $\lambda-\mu=4$. Then $(\lambda)\O_K = I^2J$ where $I,J$ are fractional ideals with $J$ being an $S$-ideal.
\end{lemma}
\begin{proof}
This is \cite[Lemma 17]{moc22}.
\end{proof}

\subsection{Proof of Theorem~\ref{maintheoremA}} 

The proof follows closely the proof of \cite[Theorem 3]{moc22}. Let $K$ be a number field with $\Cl_{S_K}(K)[2]=\{1\}$.  If $K$ is not totally real, we assume both Conjecture~\ref{conj1} and Conjecture~\ref{conj2} hold for $K$. We have so far proven that a putative non-trivial solution $(a,b,c)$ to \eqref{maineqn}  with $\widetilde{\frakP}\mid b$ yields an elliptic curve $E'/K$ with a $K$-rational point of order $2$ having potentially good reduction outside $S_K$ by Theorem~\ref{levellowerinandeichlershimura}. Hence, by Lemma \ref{lmm:bijection} we get a model
\begin{equation*}
    E': Y^2=X^3+a'X^2+b'X
\end{equation*}
with arithmetic invariants $\Delta_{E'}=2^4b'^2(a'^2-4b')$ and $j_{E'}=2^8\frac{(a'^2-3b')^3}{b'^2(a'^2-4b')}$. Further, by Theorem \ref{levellowerinandeichlershimura} (i), we know that $E'$ has good reduction outside $S_K$ which implies that $v_{\frakq}(j_{E'})\geq 0$ for
$\frakq\not\in S_K$, whence $j_{E'}\in \O_{S_K}$. Set $\lambda:=\frac{a'^2}{b'}$ and $\mu:=\lambda-4=\frac{a'^2-4b'}{b'}$. We now claim that $\lambda=u\gamma^2$ where $u$ is an $S_K$-unit. Indeed, it follows from Lemma \ref{lmm:fractionalideal} that
\begin{equation*}
    (\lambda)\O_K=I^2J,
\end{equation*}
where $J$ is an $S_K$-ideal. Therefore, $[I]^2=[J]$ as elements of the class group $\Cl(K)$ and $[J]\in \langle [\frakP]\rangle_{\frakP\in S_K}$. This implies that $[I]\in \Cl_{S_K}(K)[2]$. As we assume that $\Cl_{S_K}(K)[2]=\{1\}$, we see that $[I]\in \langle [\frakP]\rangle_{\frakP\in S_K}$. In particular, we have $I=\gamma \widetilde{I}$, where $\widetilde{I}$ is an $S_K$-ideal and $\gamma\in \O_K$. Thus,
\begin{equation*}
    (\lambda)\O_K=(\gamma)^2\widetilde{I}^2J,
\end{equation*}
where both $\widetilde{I}$ and $J$ are $S_K$-ideals. It then follows that $\left(\tfrac{\lambda}{\gamma^2}\right)\O_K$ is an $S_K$-ideal, which implies that $u:=\frac{\lambda}{\gamma^2}$ is an $S_K$-unit. By setting $\alpha:=\frac{\mu}{u}\in \mathcal{O}_{S_K}^\times$ and $\beta:=\frac{4}{u}\in \mathcal{O}_{S_K}^\times$, we obtain
\begin{equation*}
    \alpha+\beta=\gamma^2.
\end{equation*}

Since we assume $|v_{\widetilde{\frakP}}(\alpha/\beta)|\leq 6v_{\widetilde{\frakP}}(2)$, using $\alpha/\beta=\mu/4$ we see that
\begin{equation*}
    -4 v_{\widetilde{\frakP}}(2) \leq v_{\widetilde{\frakP}}(\mu) \leq 8 v_{\widetilde{\frakP}}(2).
\end{equation*}

Note that $j_{E'}=2^8(\mu+1)^3\mu^{-1}$, whence
\begin{equation*}
    v_{\widetilde{\frakP}}(j_{E'})=8v_{\widetilde{\frakP}}(2)+3v_{\widetilde{\frakP}}(\mu+1)-v_{\widetilde{\frakP}}(\mu).
\end{equation*}

We have three cases to consider depending on the valuation of $\widetilde{\frakP}$ at $\mu$:

\begin{itemize}
    \item [\textbf{Case (1):}] Suppose $v_{\widetilde{\frakP}}(\mu)= 0$, which implies that $v_{\widetilde{\frakP}}(\mu+1)\geq 0$. Therefore, we see that $v_{\widetilde{\frakP}}(j_{E'})\geq 0$, which gives a contradiction.

    \item [\textbf{Case (2):}] Suppose $v_{\widetilde{\frakP}}(\mu)>0$, which implies that $v_{\widetilde{\frakP}}(\mu+1)=0$. It follows from $v_{\widetilde{\frakP}}(\mu) \leq 8 v_{\widetilde{\frakP}}(2)$ that $v_{\widetilde{\frakP}}(j_{E'})\geq 0$, which gives a contradiction.

    \item [\textbf{Case (3):}]  Suppose $v_{\widetilde{\frakP}}(\mu)<0$, which implies that $v_{\widetilde{\frakP}}(\mu+1)=v_{\widetilde{\frakP}}(\mu)$. It follows from $  -4 v_{\widetilde{\frakP}}(2) \leq v_{\widetilde{\frakP}}(\mu)$ that $v_{\widetilde{\frakP}}(j_{E'})\geq 0$, which gives a contradiction.
\end{itemize}

All three cases lead to contradictions; hence, we conclude the proof of Theorem \ref{maintheoremA}.

\subsection{The proof of Theorem \ref{maintheoremB}}

The result will follow from Theorem \ref{maintheoremA}. Consider the equation
\begin{equation}\label{S_unit_equation}
    \alpha + \beta = \gamma^2, \quad \alpha, \beta \in \mathcal{O}_{S_K}^\times, \ \gamma \in \mathcal{O}_{S_K}.
\end{equation}

There is a natural scaling action of $\mathcal{O}_{S_K}^\times$ on the solutions. We regard two solutions 
\[
(\alpha_1, \beta_1, \gamma_1) \sim_2 (\alpha_2, \beta_2, \gamma_2)
\]
as equivalent if there exists some $\varepsilon \in \mathcal{O}_{S_K}^\times$ such that
\[
\alpha_2 = \varepsilon^2 \alpha_1, \quad \beta_2 = \varepsilon^2 \beta_1, \quad \text{and} \quad \gamma_2 = \varepsilon \gamma_1.
\]

Note that by \cite[Theorem 39]{moc22}, Equation \ref{S_unit_equation} has a finite number of solutions up to the equivalence relation $\sim_2$. Further, these are effectively computable.

Let $(\alpha,\beta,\gamma)\in \left(\calO_{S_K}^\times \right)^2\times \calO_{S_K}$ be a solution to the equation above. By scaling the equation by 
a proper element $\varepsilon \in \mathcal{O}_{S_K}^\times$ and swapping $\alpha$ and $\beta$ if necessary, we may assume $0\leq v_{\frakP}(\beta)\leq v_{\frakP}(\alpha)$ with $v_{\frakP}(\beta)\in \{0,1\}$ and $v_{\frakq}(\beta)=0$ for every odd prime $\frakq\in S_K$. One can now apply the same argument presented in the proof of \cite[Theorem 5]{moc22} to conclude the proof.

\subsection{The proof of Theorem \ref{maintheoremC}}

Let $q$ be a rational prime such that $q\geq 13$ and $q\equiv 5 \pmod{8}$, and $K=\mathbb Q(\sqrt{q})$. Then $2$ is inert in $K$, and it follows from that $2\nmid h_K^+$.  Let $\ell\geq 29$ be a prime satisfying $\ell \equiv 5 \pmod 8$ and $\left(\frac{q}{\ell} \right)=-1$. We then have that both $2$ and $\ell$ are inert in $K$, so $S_K=\{2,\ell\}$.

It follows from Theorem \ref{maintheoremB} that it is enough to check that every solution $(\alpha,\gamma)\in \calO_{S_K}^\times\times \calO_{S_K}$ with $v_{\frakP}(\alpha)\geq 0$ to the equation $\alpha+1=\gamma^2$ satisfies  $v_{\frakP}(\alpha)\leq 6$. From the equation, one can obtain that $(\gamma+1)(\gamma-1)=\alpha$. Set $x=\frac{(\gamma+1)}{2}$ and $y=\frac{(1-\gamma)}{2}$. Since they are the factors of the $S_K$-unit $\alpha$, we have $x,y\in \calO_{S_K}^\times$. It follows from \cite[Lemma 7.4]{HD} that the only solutions to the $S_K$-unit equation $x+y=1$ are $(-1,2), (1/2, 1/2), (2,-1)$. This leads to $ \alpha \in \{-1, 8\}$, and hence  $ v_{\frakP}(\alpha) \in \{0, 3\}$, proving $  v_{\frakP}(\alpha) \leq 6$. Thus, we can conclude the proof by Theorem \ref{maintheoremB}.

\section{Effective results over real and imaginary quadratic fields for signature $(p,p,2)$}\label{eff}

In this section, we study the equation
\begin{equation}\label{dfermat}
    x^p+dy^p=c^2
\end{equation} over various imaginary and real quadratic fields in which there is a unique prime $\frakP$ lying over $2$. This list currently contains $d=3,11,19,43$ for imaginary quadratic fields $\mathbb{Q}(\sqrt{-d})$ and $d=3,5,11,13,19,29$ for real quadratic fields $\mathbb{Q}(\sqrt{d})$; however, the list may grow if we can extend the form elimination computations. 

Recall that if $(a,b,c)$ is a solution to the Equation (\ref{dfermat}) with $a,b,c \in \mathcal{O}_K$, then the triple $(a,db,c)$ is called primitive if $a,db$ and $c$ are pairwise coprime. Our main results for the effective cases are as follows.

\begin{theorem}\label{maintheoremfofrimaginaryquadraticfields}
Let $K=\Q(\sqrt{-d})$ where $d\in \{3, 11,19, 43\}$. Assume that Conjecture~\ref{conj1} holds for $K$. Write $\frakP=2\mathcal O_K$.  Then, the equation 
     $$x^p+dy^p=z^2$$
     has no non-trivial solutions $(a,b,c)$ with $a,b,c \in \mathcal{O}_K$ such that $(a,db,c)$ is primitive and $\frakP\mid b$ when $p>C_K$ and $p \neq d$, where \[ C_K=
\left\{\begin{array}{l}
17 \text {, if $d=3,11,43$ } \\
19\text {, if $d=19$}.
\end{array}\right.\] 
 \end{theorem}

 For the real case, we do not need to assume Conjecture \ref{conj1} since we have Theorem \ref{level lowering}.

\begin{theorem}\label{thm1:dfermat}
    Let $K=\mathbb{Q}(\sqrt{d})$, where $d\in\{3,5,11,13,19,29\}$. Write $\frakP^e=2\mathcal{O}_K$. Then, the equation
      $$x^p+dy^p=z^2$$
    has no non-trivial solutions $(a,b,c)$ with $a,b,c \in \mathcal{O}_K$ such that $(a,db,c)$ is primitive and $\frakP\mid b$ when $p>C_K$ and $p \neq d$, where $$C_K=
\left\{\begin{array}{l}
17 \text {, if $d=3,5,11,13$ } \\
19\text {, if $d=19$ }\\
17\text {, if $d=29$. }
\end{array}\right.$$

\end{theorem}

\begin{remark}
 In the proofs of Theorem \ref{thm1:dfermat} and Theorem \ref{maintheoremfofrimaginaryquadraticfields}, we associate another elliptic curve, namely $E_1/K$ (given by Equation \ref{Frey-effective}) to the Diophantine equation (\ref{dfermat}) since the previously associated elliptic curve $E/K$ given by Equation \ref{Frey} is not useful to get effective results.
\end{remark}

