\begin{theorem}\label{maintheoremB}
   Let $K$ be a number field with $2\nmid h_K^+$ in which $2$ is inert. In the case where $K$ is not totally real, we assume both Conjecture~\ref{conj1} and Conjecture~\ref{conj2} hold for $K$. Let $\frakP$ be the only prime above $2$. Suppose that every solution $(\alpha,\gamma)\in \calO_{S_K}^\times\times \calO_{S_K}$ with $v_{\frakP}(\alpha)\geq 0$ to the $S$-unit equation
    \begin{equation}\label{unitequation2}
        \alpha+1=\gamma^2
    \end{equation}    
satisfies  $v_{\frakP}(\alpha)\leq 6$. Then, there is a constant  $V=V(A,B,C,K)$ depending only on $K,A,B$ and $C$ such that the equation $ Ax^p+By^p=Cz^2$ does not have any non-trivial primitive solution $(a,b,c)$ in  $\calO_K^3$ with $\frakP \mid b$ for $p > V$. 
\end{theorem}

ref_dict.thm:ES:
\begin{theorem} \label{thm:ES}
	Let $K$ be a totally real field and let $\frakf$  be a Hilbert
	newform over $K$ of level $\mathcal N$ and parallel weight $2$, such that $\Q_\frakf = \Q$. 

	\begin{enumerate}
		\item If the degree of $K$ over $\Q$ is odd then there is an elliptic curve $E_\frakf/K$ of conductor $\mathcal N$ with the same $L$-function as $\frakf$. (Blasius \cite{Blas04}, Hida \cite{Hida})

		\item Let $p$ be an odd prime and $\frakq\nmid p$ be a prime of $K$.  Suppose $\bar{\rho}_{E,p}$ is irreducible, and $\bar{\rho}_{E,p} \sim \bar{\rho}_{\frakf,p}$ with the following properties:
		\begin{enumerate}
			\item $E$ has potentially multiplicative reduction at $\frakq$,
			\item $p \mid  \# \bar{\rho}_{E,p}(I_\frakq) $ where $I_\frakq$ denotes the inertia group at $p$,
			\item $p \nmid (\text{Norm}_{K/\Q}(\frakq) \pm 1)$,
		\end{enumerate}
		then there is an elliptic curve $E_\frakf/K$ of conductor $\mathcal N$ with the same $L$-function as $\frakf$. (Freitas-Siksek Corollary 2.2 in \cite{FS})
	\end{enumerate}
\end{theorem}

ref_dict.thm1:dfermat:
\begin{theorem}\label{thm1:dfermat}
    Let $K=\mathbb{Q}(\sqrt{d})$, where $d\in\{3,5,11,13,19,29\}$. Write $\frakP^e=2\mathcal{O}_K$. Then, the equation
      $$x^p+dy^p=z^2$$
    has no non-trivial solutions $(a,b,c)$ in $\calO_K^3$ such that $(a,db,c)$ is primitive and $\frakP\mid b$ when $p>C_K$ and $p \neq d$, where $$C_K=
\left\{\begin{array}{l}
17 \text {, if $d=3,5,11,13$ } \\
19\text {, if $d=19$ }\\
17\text {, if $d=29$. }
\end{array}\right.$$
\end{theorem}

post_theorem_intro_text:
Theorem \ref{maintheoremA} generalizes \cite[Theorem 3]{moc22} and \cite{KS24aa,KS24bb}, which are restricted to totally real number fields and certain coefficients. The generality in our setting is achieved by employing a slightly modified level-lowering technique, adapted from \cite[\S 7]{SS} and \cite[\S 3]{isik2023ternary}, originally developed for different Fermat equations. A slight downside of this method is that we need to assume two conjectures (Conjecture~\ref{conj1} and Conjecture~\ref{conj2}) in the general setting. In the totally real case, one can avoid such conjectures using Proposition \ref{modularityoffreycurveovertotallyreal} and Theorem \ref{thm:ES}.

Furthermore, we obtain the following theorem by imposing some local constraints.

\begin{theorem}\label{maintheoremB}
   Let $K$ be a number field with $2\nmid h_K^+$ in which $2$ is inert. In the case where $K$ is not totally real, we assume both Conjecture~\ref{conj1} and Conjecture~\ref{conj2} hold for $K$. Let ${\mathfrak P}$ be the only prime above $2$. Suppose that every solution $(\alpha,\gamma)\in \calO_{S_K}^\times\times \calO_{S_K}$ with $v_{{\mathfrak P}}(\alpha)\geq 0$ to the $S$-unit equation
    \begin{equation}\label{unitequation2}
        \alpha+1=\gamma^2
    \end{equation}    
satisfies  $v_{{\mathfrak P}}(\alpha)\leq 6$. Then, there is a constant  $V=V(A,B,C,K)$ depending only on $K,A,B$ and $C$ such that the equation $ Ax^p+By^p=Cz^2$ does not have any non-trivial primitive solution $(a,b,c)$ in  $\calO_K^3$ with ${\mathfrak P} \mid b$ for $p > V$. 
\end{theorem}

\vspace{1em}
In particular, we obtain the following result when we apply the above theorem to real quadratic fields.
\begin{theorem}\label{maintheoremC}
   Let $q$ be a rational prime such that $q\geq 13$ and $q\equiv 5 \pmod{8}$, and $K=\mathbb Q(\sqrt{q})$. Let $\ell\geq 29$ be a prime satisfying $\ell \equiv 5 \pmod 8$ and $\left(\frac{q}{\ell} \right)=-1$. Then, there is a constant $B_{K,\ell}$ depending only on $K$ and $\ell$ such that the Fermat equation
\[
x^p +\ell^r y^p = z^2
\]
has no any non-trivial primitive solution $(a,b,c)$ in  $\calO_K^3$ with ${\mathfrak P}=2\mathcal{O}_K\mid b$ for $p > B_{K,\ell}$.
\end{theorem}

\begin{remark}
    As we can see from the statement, the proof of Theorem~\ref{maintheoremA} will depend on the solutions to $S$-unit equation \eqref{unitequation}. It is known that, for a given number field $K$ and a finite set of primes $S$, the $S$-unit equation \eqref{unitequation} has only finitely many solutions up to an equivalence relation (see \cite[Theorem 39]{moc22}). Although there is no theoretical obstruction, it becomes practically challenging to find all the solutions when $[K:\mathbb Q]$ or $|S|$ is too large.
\end{remark}

We restrict ourselves to the case $A = C = 1$ and $B = d$ when working over imaginary and real quadratic fields for effective results.
\begin{theorem}\label{maintheoremfofrimaginaryquadraticfields}
     Let $K={\mathbb Q}(\sqrt{-d})$ where $d\in \{3, 11,19, 43\}$. Assume Conjecture~\ref{conj1} holds for $K$. Write ${\mathfrak P}=2\mathcal O_K$.  Then, the equation 
     $$x^p+dy^p=z^2$$
     has no non-trivial solutions $(a,b,c)$ in $\calO_K^3$ such that $(a,db,c)$ is primitive and ${\mathfrak P}\mid b$ when $p>C_K$ and $p \neq d$, where \[ C_K=
\left\{\begin{array}{l}
17 \text {, if $d=3,11,43$ } \\
19\text {, if $d=19$}.
\end{array}\right.\]
 \end{theorem}

\begin{theorem}\label{thm1:dfermat}
    Let $K=\mathbb{Q}(\sqrt{d})$, where $d\in\{3,5,11,13,19,29\}$. Write ${\mathfrak P}^e=2\mathcal{O}_K$. Then, the equation
      $$x^p+dy^p=z^2$$
    has no non-trivial solutions $(a,b,c)$ in $\calO_K^3$ such that $(a,db,c)$ is primitive and ${\mathfrak P}\mid b$ when $p>C_K$ and $p \neq d$, where $$C_K=
\left\{\begin{array}{l}
17 \text {, if $d=3,5,11,13$ } \\
19\text {, if $d=19$ }\\
17\text {, if $d=29$. }
\end{array}\right.$$
\end{theorem}

\begin{remark}
    In the appendix, we will also introduce effective results for the generalized Fermat equation of signature $(p,p,3)$ with coefficients $A=C=1$, $B=d$ over certain real quadratic fields $\mathbb{Q}(\sqrt{d})$.
\end{remark}

\subsection*{Organization of the paper} 

In Section \ref{FreyCurve}, we associate an elliptic curve (Frey curve) to a putative solution of Equation \ref{maineqn} and prove relevant facts. In Section \ref{modularity}, we provide the theoretical background we need concerning modularity to prove our results. In Section \ref{level},  we prove the irreducibility of the mod $p$ Galois
representation $\overline{\rho}_{E,p}$ associated to the Frey elliptic curve and  we relate it with another representation of lower level via a new elliptic curve $E'$ whose conductor is independent of the solution. In Section \ref{asy}, we prove the asymptotic results namely Theorems \ref{maintheoremA}, \ref{maintheoremB} and \ref{maintheoremC}. In Section \ref{eff}, we give the proofs of effective results, Theorems \ref{maintheoremfofrimaginaryquadraticfields} and \ref{thm1:dfermat}. And finally, in the Appendix we prove results regarding effective solutions of another Diophantine equation $x^p+dy^p=z^3$.

All computational claims in this paper were carried out using \texttt{Magma}. The associated codes are available in the GitHub repository:
\begin{small}

\url{https://github.com/BGCakti/Solving-equations-of-signature-p-p-2-with-coefficients}.
\end{small}

