ref_dict.theorem:universal:
\begin{theorem}
\label{theorem:universal}
Let $\Spots$ be a bilateral, local parking procedure. Then the number of $\Spots$-parking functions of length $r$ is given by $(r+1)^{r-1}$.
\end{theorem}

ref_dict.thm:main:
\begin{thm}\label{thm:main}
    For any $0<\alpha<1$, there exists a constant $C_\alpha>0$ such that the following holds. Let $p$ be a prime and let $S\subseteq \mathbb{Z}_p \setminus \{0\}$ be a subset with $C_\alpha\le |S|\le p^{1-\alpha}$. Then there exists a valid ordering of $S$, i.e.\ there is an ordering $s_1,s_2,\dots,s_{|S|}$ of the elements of $S$ such that all partial sums $s_1,s_1+s_2,\dots,s_1+s_2+\dots+s_{|S|}$ are distinct.  
\end{thm}

ref_dict.coro:anticonc:
\begin{cor}\label{coro:anticonc}
    For any $0<\eps<1$ There exists a constant $C'_\eps>0$ such that the following holds. Let $p$ be a prime, let $S\subseteq \mathbb{Z}_p$ be a subset of size $|S|\ge 2$, and consider a positive integer $m\le (1-\eps)|S|$. Now, let $R\su S$ be a uniformly random subset of $S$ of size $m$, and let  $\Sigma(R) = \sum_{x\in R}x\in \mathbb{Z}_p$ be the sum of the elements of $R$. Then 
    \[
        \max_{z\in \mathbb{Z}_p} \mathbb{P}[\Sigma(R)=z] \le \frac{1}{p} + \frac{C'_\eps\sqrt{\log |S|}}{|S|\sqrt{m}}.
    \]
\end{cor}

ref_dict.thm:anticonc:
\begin{thm}\label{thm:anticonc}
    There exists an absolute constant $C>0$ such that the following holds. Let $p$ be a prime, let $S\subseteq \mathbb{Z}_p$ be a subset of size $|S|\ge 2$, and let $m$ be an integer with $C\log |S|\le m\le 10^{-3}|S|/\log |S|$. Now, let $R\su S$ be a uniformly random subset of $S$ of size $m$, and let  $\Sigma(R) = \sum_{x\in R}x\in \mathbb{Z}_p$ be the sum of the elements of $R$. Then 
    \[
        \max_{z\in \mathbb{Z}_p} \mathbb{P}[\Sigma(R)=z] \le \frac{1}{p} + \frac{C}{|S|\sqrt{m}}.
    \]
\end{thm}

