ref_dict.maintheore:
\begin{theo} \label{maintheore}
Let $U \subset \mathbb{R}^d$ be a (possibly unbounded) open set with $d \geq 2$. Assume that $\mathbf{G} \in L^2_{loc}(U, \mathbb{R}^d)$ and $c \in L^1_{loc}(U)$. Let $A = (a_{ij})_{1 \leq i,j \leq d}$ be a symmetric matrix of functions such that $a_{ij} \in VMO_{loc}(U)$ for all $1 \leq i,j \leq d$ (see Definition~\ref{defnvmo}), and suppose that ${\rm div} A \in L^2_{loc}(U, \mathbb{R}^d)$ (see Definition~\ref{defndivmat}). Also assume that $A$ is locally uniformly strictly elliptic and bounded on $U$, i.e. for every open ball $V$ with $\overline{V} \subset U$, there exist constants $\lambda_V, M_V > 0$ such that
\begin{equation} \label{locellst}
\lambda_V \| \xi \|^2 \leq \langle A(x) \xi, \xi \rangle, \quad \;\; \max_{1 \leq i,j \leq d} |a_{ij}(x)| \leq M_V
\quad \text{for a.e. } x \in V \text{ and all } \xi \in \mathbb{R}^d.
\end{equation}
Let $\tilde{\mathbf{F}} \in L^2_{loc}(U, \mathbb{R}^d)$ and $\tilde{f} \in L^1_{loc}(U)$. Suppose that $h \in L^{\infty}_{loc}(U)$ satisfies
\[
\int_U \left({\rm trace}(A \nabla^2 \varphi) + \langle \mathbf{G}, \nabla \varphi \rangle + c \varphi \right) h \, dx 
= \int_U \tilde{f} \varphi \, dx + \int_U \langle \tilde{\mathbf{F}}, \nabla \varphi \rangle \, dx \quad \text{for all } \varphi \in C_0^{\infty}(U).
\]
Then $h \in H^{1,2}_{loc}(U)$.
\end{theo}

ref_dict.defndivmat:
\begin{defn} \label{defndivmat}
Let $U$ be an open subset of $\mathbb{R}^d$, $\mathbf{E} = (e_1, \dots, e_d) \in L^1_{loc}(U, \mathbb{R}^d)$ and $B = (b_{ij})_{1 \leq i,j \leq d}$ be a (possibly non-symmetric) matrix of functions with $b_{ij} \in L^1_{loc}(U)$ for all $1 \leq i,j \leq d$. Let $\mathbf{F} \in L^1_{loc}(U, \mathbb{R}^d)$ and $f \in L^1_{loc}(U)$.
\begin{itemize}
\item[(i)] We say that ${\rm div} B = \mathbf{E}$ if
\[
\int_U \sum_{i,j=1}^d b_{ij} \, \partial_i \phi_j \, dx = - \int_U \sum_{j=1}^d e_j \, \phi_j \, dx \quad \text{for all } (\phi_1, \dots, \phi_d) \in C_0^\infty(U)^d.
\]
\item[(ii)] We say that ${\rm div} \mathbf{F} = f$ if
\[
\int_U \langle \mathbf{F}, \nabla \varphi \rangle \, dx = - \int_U f \varphi \, dx \quad \text{for all } \varphi \in C_0^\infty(U).
\]
\end{itemize}
\end{defn}

theorem.content:
\label{thm1x}
Let $\Phi$, $\Psi$ be linear flows on $X$. Then each of the following
four statements implies the other three:
\begin{enumerate}
\item $\Phi \stackrel{1}{\thicksim} \Psi$, i.e., $\Phi$, $\Psi$ are
  Lipschitz equivalent;
  \item there exists $\alpha
    \in \mathbb{R} \setminus \{0\}$ so that $\Phi \stackrel{1}{\cong}
    \Psi_{*\alpha}$, i.e., $\Phi$, $\Psi_{*\alpha}$ are Lipschitz conjugate;
\item there exists $\beta
    \in \mathbb{R} \setminus \{0\}$ so that $A^{\Phi}$, $\beta A^{\Psi}$ are
    Lyapunov similar while $A^{\Phi_{\sf  AD}}$, $\beta A^{\Psi_{\sf
        AD}}$ as well as $A^{\Phi_{\sf  C}}$, $\beta A^{\Psi_{\sf
        C}}$ are similar;
\item there exists $\gamma
    \in \mathbb{R} \setminus \{0\}$ so that $A^{\Phi}$, $\gamma A^{\Psi}$ are
    Lipschitz similar while $A^{\Phi_{\sf  C}}$, $\gamma A^{\Psi_{\sf
        C}}$ are similar.
  \end{enumerate}
  Moreover, $\Phi \stackrel{1}{\cong}\Psi$ if and
only if $A^{\Phi}$, $A^{\Psi}$ are Lipschitz similar while $A^{\Phi_{\sf  C}}$, $ A^{\Psi_{\sf
        C}}$ are similar.

ref_dict.prop1za:
\begin{prop}\label{prop1za}
Let $\Phi$, $\Psi$ be linear flows on $X$. Then each of the following
three statements implies the other two:
\begin{enumerate}
\item $\Phi \stackrel{1^-}{\thicksim} \Psi$, i.e., $\Phi$, $\Psi$ are
  H\"{o}lder equivalent;
  \item there exists $\alpha
    \in \R \setminus \{0\}$ so that $\Phi \stackrel{1^-}{\cong}
    \Psi_{*\alpha}$, i.e., $\Phi$, $\Psi_{*\alpha}$ are H\"{o}lder conjugate;
\item there exists $\beta
    \in \R \setminus \{0\}$ so that $A^{\Phi}$, $\beta A^{\Psi}$ are
    Lyapunov similar while $A^{\Phi_{\sf C}}$, $\beta A^{\Psi_{\sf
        C}}$ are similar.
  \end{enumerate}
  Moreover, $\Phi \stackrel{1^-}{\cong} \Psi$ if and only if
  $A^{\Phi}$, $A^{\Psi}$ are Lyapunov similar while $A^{\Phi_{\sf C}}$,
  $ A^{\Psi_{\sf C}}$ are similar.
\end{prop}

