\begin{prop}\label{prop1zb}
Let $\Phi$, $\Psi$ be linear flows on $X$. Then each of the following
five statements implies the other four:
\begin{enumerate}
\item $\Phi \stackrel{\sf lin}{\thicksim} \Psi$, i.e., $\Phi$, $\Psi$ are
  linearly equivalent;
 \item $\Phi \stackrel{\sf diff}{\thicksim} \Psi$, i.e., $\Phi$, $\Psi$ are
  differentiably equivalent;
  \item there exists $\alpha
    \in \R \setminus \{0\}$ so that $\Phi \stackrel{\sf lin}{\cong}
    \Psi_{*\alpha}$, i.e., $\Phi$, $\Psi_{*\alpha}$ are linearly
    conjugate;
     \item there exists $\beta
    \in \R \setminus \{0\}$ so that $\Phi \stackrel{\sf diff}{\cong}
    \Psi_{*\beta}$, i.e., $\Phi$, $\Psi_{*\beta}$ are differentiably conjugate;
\item there exists $\gamma
    \in \R \setminus \{0\}$ so that $A^{\Phi}$, $\gamma A^{\Psi}$ are similar.
  \end{enumerate}
  Moreover, $\Phi \stackrel{\sf lin}{\cong} \Psi$ if and only if $\Phi
  \stackrel{\sf diff}{\cong} \Psi$ if and only if $A^{\Phi}$,
  $A^{\Psi}$ are similar. 
\end{prop}

