ref_dict.prop:imprimitive-equiv-decomposition:
\begin{proposition} \emph{\cite[Theorem 27]{Burda2012Topological}}
\label{prop:imprimitive-equiv-decomposition}
    Let $X \subseteq \mathbb{C}$ be an open connected set and $f:X\to\mathbb{C}$ be a meromorphic map with monodromy group $G$. Then $G$ is imprimitive if and only if $f$ can be expressed as a composition $(h\circ g)(x)$ of two meromorphic functions $g:X\to Y$ and $h:Y\to\mathbb{C}$ for some open connected set $Y\subseteq\mathbb{C}$. Moreover, the monodromy groups of $g$ and $h$ are quotients of $G$.
\end{proposition}

ref_dict.thm:wielandt:
\begin{theorem}\emph{(Wielandt, \cite[Theorem 29.2]{neumann2023infinitepermutationgroups})}
\label{thm:wielandt}
    Let $S$ be an infinite set and $G$ be a primitive group acting on $S$. If $G$ contains a non-identity permutation with finite support, then $\alt(S)\leq G$.
\end{theorem}

expanded_sketch:
The provided proof combines the following theorem on primitive group actions on infinite sets.

\begin{theorem}\emph{(Wielandt, \cite[Theorem 29.2]{neumann2023infinitepermutationgroups})}
\label{thm:wielandt}
    Let $S$ be an infinite set and $G$ be a primitive group acting on $S$. If $G$ contains a non-identity permutation with finite support, then $\alt(S)\leq G$.
\end{theorem}

It also uses the following relation between primitivity and decompositions.

\begin{proposition} \emph{\cite[Theorem 27]{Burda2012Topological}}
\label{prop:imprimitive-equiv-decomposition}
    Let $X \subseteq \mathbb{C}$ be an open connected set and $f:X\to\mathbb{C}$ be a meromorphic map with monodromy group $G$. Then $G$ is imprimitive if and only if $f$ can be expressed as a composition $(h\circ g)(x)$ of two meromorphic functions $g:X\to Y$ and $h:Y\to\mathbb{C}$ for some open connected set $Y\subseteq\mathbb{C}$. Moreover, the monodromy groups of $g$ and $h$ are quotients of $G$.
\end{proposition}

Both ingredients are stated, for example, in the doctoral work of Burda on algebraic functions.

ref_dict.absorption:
\begin{lemma}\label{absorption}
Let $u\colon\Sigma\times(T_0, T)\to \R$ be a solution to the graphical mean curvature flow  \eqref{gmcf2} with $\norm{u(\cdot,t)}_{C^1(\Sigma)}<r_0$ for all $t\in(T_0,T)$, then for any $t\in (T_0+2, T)$
\begin{equation}\label{gmcf-Schauder}
\|u\|_{C^{2,\a}(\Sigma\times(t-1,t))}\le C(\|u\|_{L^2(\Sigma\times(t-2,t))}+\|u\|_{C^{1,\alpha}(\Sigma\times(t-2,t))}\|u\|_{C^{2,\alpha}(\Sigma\times(t-2,t))})\,,
\end{equation}
where $C$ depends only on $\Sigma$, $M$ and $r_0$. 

Moreover, there exists an $\varepsilon>0$, depending only on $\Sigma$ and $M$, such that, if $\|u\|_{C^{1,\a}(\Sigma\times(T-R, T))}<\varepsilon$ for some $T-R\ge T_0$, then 
\begin{equation}\label{gmcf-SchauderII}
\|u\|_{C^{2,\a}(\Sigma\times (T-R/2,T))}\le C \|u\|_{L^2(\Sigma\times(T-R, T))} \,,
\end{equation}
where $C>0$ depends only on $\Sigma$ and $M$. 
\end{lemma}

ref_dict.uniqueness:
\begin{theorem}\label{uniqueness}
Let $u\colon\Sigma\times(-\infty, 0]\to\R$ be a smooth solution to the free boundary mean curvature flow \eqref{gmcf2}.
There exists a constant $\varepsilon>0$, depending only on $\Sigma$ and $M$
, such that if 
\begin{equation} \label{tu:assume1}
\norm{u}_{C^{1,\a}(\Sigma\times(-\infty,0])} < \varepsilon \,,
\end{equation}
and
\begin{equation} \label{tu:assume2}
\liminf_{t\to-\infty}\ \abs{t} \norm{u(\cdot,t)}_{C^0(\Sigma)} = 0 \,,
\end{equation}
then, possibly after a time translation, $u$  coincides with one of the solutions constructed in \cref{construction}.
\end{theorem}

ref_dict.thmA:
\begin{alphatheorem}[cf.\ \cref{construction,uniqueness}, \cref{COR}] \label{thmA}
Let $\Sigma$ be a free boundary minimal hypersurface of Morse index $I$ in a Riemannian manifold $(M,g)$ with convex boundary. Then there exists an $I$-parameter family of ancient free boundary mean curvature flows emanating from $\Sigma$. Moreover, any ancient solution with sufficiently fast decay to $\Sigma$ belongs to this family.
\end{alphatheorem}

theorem.content:
[{see Theorem \ref{theorem l2 del delbar lemma}}]\label{theorem intro l2 del delbar lemma}
    Let $(M,g)$ be a complete K\"ahler manifold such that the self-adjoint Laplacian $\Delta$ has a spectral gap in $L^2\Lambda^{k}_\C$. Given a smooth $L^2$-form $\alpha\in L^2A^k_\C$ which satisfies $\partial\alpha=\delbar\alpha=0$, then the following conditions are equivalent:
    \begin{enumerate}
        \item $\alpha=\partial\delbar\beta$, for $\beta\in L^2 A^{k-2}_\C$;
        \item $\alpha=\partial\gamma$, for $\gamma\in L^2 A^{k-1}_\C$;
        \item $\alpha=\delbar\zeta$, for $\zeta\in L^2 A^{k-1}_\C$;
        \item $\alpha=\partial\eta+\delbar\theta$, for $\eta,\theta\in L^2 A^{k-1}_\C$;
        \item $\alpha=d\lambda$, for $\lambda\in L^2 A^{k-1}_\C$.
    \end{enumerate}

ref_dict.theorem spectral gap varouchas laplacian:
\begin{theorem}\label{theorem spectral gap varouchas laplacians}
    Let $(M,g)$ be a complete K\"ahler manifold. 
    If $\Delta_{\delbar,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$, $L^2\Lambda^{p-1,q}$ and $L^2\Lambda^{p,q-1}$, then $\square_{A,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$. If $\Delta_{\delbar,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$, $L^2\Lambda^{p+1,q}$ and $L^2\Lambda^{p,q+1}$, then $\square_{BC,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$.
\end{theorem}

ref_dict.theorem closed image del delbar:
\begin{theorem}\label{theorem closed image del delbar}
Let $(M,g)$ be a complete K\"ahler manifold. If $\Delta_{\delbar,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$, then for $b\in\{s,w\}$ it follows that
$\im\del\delbar_b$ and $\im\delbar^*\del^*_b$ are closed in $L^2\Lambda^{p,q}$.
\end{theorem}

