\begin{theorem}\label{theorem reduced l2 del delbar lemma}
Given a complete K\"ahler manifold $(M,g)$, in both the spaces $L^2\Lambda^k_\C$ and $L^2\Lambda^{p,q}$ the following equalities hold true
\begin{align*}
\c{\im \del\delbar_s}
&=\c{\im \del_s}\cap\ker\delbar_w=\c{\im \delbar_s}\cap\ker\del_w\\
&=(\c{\im\del_s}+\c{\im\delbar_s})\cap\ker\del_w\cap\ker\delbar_w\\
&=\c{\im d_s}\cap\ker\del_w\cap\ker\delbar_w.
\end{align*}
\end{theorem}

