        \item $\alpha=\del\gamma$, for $\gamma\in L^2 A^{k-1}_\C$;
        \item $\alpha=\delbar\zeta$, for $\zeta\in L^2 A^{k-1}_\C$;
        \item $\alpha=\del\eta+\delbar\theta$, for $\eta,\theta\in L^2 A^{k-1}_\C$;
        \item $\alpha=d\lambda$, for $\lambda\in L^2 A^{k-1}_\C$.
