\begin{prop}\label{last}
    GKM graph of $Q_{\G, \lambda}$ has $2^n\cdot n!$ vertices that are labeled by pairs $(\sigma, s)$, where $\sigma \in S_n$, $s \in (\mathbb{Z}_2^n, +)$. There is an edge between two points $A_{\sigma, s}$ and $A_{\tau, s'}$ if and only if the following three relations hold true 
    \begin{enumerate}
        \item $\sigma = \tau \cdot (i,j)$ and $\{i,j\} \in E_\G$;
        \item $s_k = s_k'$ for all $k \not \in \{i, j\}$;
        \item $s_i + s_j = s'_i + s'_j$.
    \end{enumerate}

    The weights of the edges $(A_{s, \sigma}A_{s', \sigma \cdot (i,j)})$ are (or equivalently axial function): \par
    $\epsilon_i + \epsilon_j$ if $s_{i} = s'_i$, and $\epsilon_i - \epsilon_j$ if $s_{i} \not = s'_i$.
\end{prop}

ref_dict.M_GKM:
\begin{con}\label{graph}
    Let $\G = ([n], E_\G)$ be a simple graph and $\mu$ is a GKM graph of $M_{\G, \lambda}$. We construct a new graph $\eta$ as follows.\par
    For every vertex $A_{\sigma}$ of $\mu$ we make $2^n$ vertices of $\eta$ denoted by $A_{s, \sigma}$.\par
    For every edge between vertices $A_{\sigma}$ and $A_{\sigma \cdot (i,j)}$ of $\mu$ we make $2^n$ edges of $\eta$. Each of them connect following vertices: $A_{s, \sigma}$ and $A_{s', \sigma \cdot (i,j)}$, where $s_k = s'_{k}$ for all $k \not \in \{i,j\}$ and $s_{i} + s_{j} = s'_{i} + s'_{j}$. \par
    The set of edges of $\eta$ is equipped with an axial function. It is defined as follows:\par
    $\alpha(A_{s, \sigma}A_{s', \sigma \cdot (i,j)}) = \epsilon_i + \epsilon_j$ if $s_{i} = s'_i$ (equivalently $s_{j} = s'_{j}$) \par
    $\alpha(A_{s, \sigma}A_{s', \sigma \cdot (i,j)}) = \epsilon_i - \epsilon_j$ if $s_{i} \not = s'_i$ (equivalently $s_{j} \not = s'_{j}$), \par
    where $\epsilon_1,\ldots,\epsilon_n$ is the standard basis of Hom$(T^n, S^1) \cong \mathbb{Z}^n$, that is $\epsilon_i((t_1, \ldots, t_n)) = t_i$ for $i = 1, \ldots, n$.
\end{con}
   Now we formulate some known facts about isospectral Hermitian matrices. The proof may be found in \cite{A1}.

\subsection{Hermitian matrices}\label{M_GKM}
As we already said there is a $T^n$-action on $M_{\G, \lambda}$. The following statements help us describe the GKM graph of $M_{\G, \lambda}$.
\begin{prop}
    \cite[Remark 2.33]{A1}  Independently of $\G$, the torus action on $M_{\G, \lambda}$ has exactly $n!$ isolated fixed points. Fixed points are given by the diagonal Hermitian matrices $A_\sigma = diag(\lambda_{\sigma(1)}, \ldots, \lambda_{\sigma(n)})$.
\end{prop}

So the vertices of GKM graph are determined.

\begin{prop}
    \cite[Lemma 2.36]{A1} If $\sigma = \tau \cdot (i,j)$ with $(i, j) \in E_{\G}$, then the matrices $A_{\sigma}$ and $A_{\tau}$ are connected by a 2-sphere of isospectral matrices of the form
    $$
    \begin{pmatrix}
        \lambda_{\sigma(1)} & 0 & & \cdots & & 0\\
        0 & \ddots & &  &\\
        & & * & * &  & \vdots\\
        \vdots & & * & * & &\\
        & & & & \ddots & 0\\
        0 & & \cdots & & 0 & \lambda_{\sigma(n)}
    \end{pmatrix}
    =
    \begin{pmatrix}
        \lambda_{\tau(1)} & 0 & & \cdots & & 0\\
        0 & \ddots & &  &\\
        & & * & * &  & \vdots\\
        \vdots & & * & * & &\\
        & & & & \ddots & 0\\
        0 & & \cdots & & 0 & \lambda_{\tau(n)}
    \end{pmatrix}
    $$
    with the block on positions $(i,j)$.
\end{prop}

Since these 2-spheres are also $T$-invariant they correspond to some edges of the $M_{\G, \lambda}$ GKM graph. It remains to determine whether these are all edges of the graph.

The following statements ensure that there are no more edges in the GKM graph of $M_{\G, \lambda}$.

\begin{prop} \cite[Remark 2.33]{A1}
    For $i < j$ let us introduce the vector subspace $V_{ij} \subset M_n$:
    $$V_{ij} = \{A = (a_{i', j'})\,| \, a_{i', j'} = 0 \; \text{unless} \; (i', j') = (i,j)\; or \; (j,i)\}
    $$
    Then space $V_{ij}$ is $T$-invariant and $V_{ij}$ is the irreducible real 2-dimensional representation at point $A_\sigma$ with weight $\epsilon_i - \epsilon_j$, where $\epsilon_1, \ldots, \epsilon_n$ is the standard basis of Hom$(T^n, S^1) \cong \mathbb{Z}^n$, that is $\epsilon_i((t_1, \ldots, t_n)) = t_i$ for $i = 1, \ldots, n$.
\end{prop}

\begin{cor}
    At any fixed point $A_\sigma$, the tangent representation $T_{A_{\sigma}}M_{\G, \lambda}$ has weights of the form
    $ \{\epsilon_i - \epsilon_j\,|\, \{i,j\} \in \G\}$.
     Moreover, $T_{A_{\sigma}}M_{\G, \lambda} = \bigoplus\limits_{\{i,j\}\in E_{\G}} V_{ij}$.
\end{cor}

Since we know the tangent representation at every fixed point, and dimensions are equal, we can conclude that we observed all edges of the GKM graph. Now we can describe this graph.
\begin{prop}\label{Her}
    GKM graph of $M_{\G, \lambda}$ consists of $n!$ points that are labeled by the permutations $\sigma$. There is an edge between two points $A_{\sigma}$ and $A_{\tau}$ if and only if  $\sigma = \tau \cdot (i,j)$ and $\{i,j\} \in E_\G$.
\end{prop}

\subsection{Skew-symmetric matrices}
In this subsection we will finally obtain a GKM graph for $Q_{\G,\lambda}$ manifold. As a result Theorem~\ref{Th} will be proved.

\begin{prop}\label{need}
    Fixed points of $Q_{\G,\lambda}$ are "almost diagonal" matrices $A_{\sigma, s}$ for $\sigma \in S_n$, $s \in (\mathbb{Z}_2^n, +)$ where
    $$
    A_{\sigma, s} = 
    \begin{pmatrix}
    \begin{bmatrix}
    0        & (-1)^{s_1} \cdot \lambda_{\sigma(1)} \\
    -(-1)^{s_1} \cdot\lambda_{\sigma(1)}       & 0 
    \end{bmatrix}
    & \hdotsfor[1.5]{4} &
    \begin{bmatrix}
        0 &&&&&&&& 0 \\
        0 &&&&&&&& 0
    \end{bmatrix} \\
    \vdots & & & & \ddots &  \vdots \\
    \begin{bmatrix}
        0 &&&&&&&& 0 \\
        0 &&&&&&&& 0
    \end{bmatrix}
     & \hdotsfor[1.5]{4} &
     \begin{bmatrix}
    0        & (-1)^{s_n} \cdot\lambda_{\sigma(n)} \\
    -(-1)^{s_n} \cdot\lambda_{\sigma(n)}       & 0 
    \end{bmatrix}

\end{pmatrix}$$
\end{prop}

\begin{proof}
    We have an action on $Q_{\G,\lambda}$ of matrices of the form 
  $$  
\begin{pmatrix}
    \begin{bmatrix}
    \cos\phi        & \sin\phi \\
    -\sin\phi       & \cos\phi
    \end{bmatrix}
    & \hdotsfor[1.5]{2} &
    \begin{bmatrix}
        0 & 0 \\
        0 & 0
    \end{bmatrix} \\
    \vdots &
    \begin{bmatrix}
     \cos\psi        & \sin\psi  \\
    -\sin\psi        & \cos\psi 
    \end{bmatrix}
             &   &  \vdots  \\
    \vdots &   & \ddots &  \vdots \\
    \begin{bmatrix}
        0 & 0 \\
        0 & 0
    \end{bmatrix}
     & \hdotsfor[1.5]{2} &
    \begin{bmatrix}
     \cos\theta        & \sin\theta   \\
    -\sin\theta        & \cos\theta 
    \end{bmatrix}
\end{pmatrix}
$$
by conjugation. It is obvious that only blocks $(i, i)$ and $(j, j)$ of this matrix act on a block $(i, j)$ of matrix from $Q_{\G,\lambda}$. So we can consider a case of matrix consisting of 4 blocks:

 $$  
 \begin{pmatrix}
    \begin{bmatrix}
    \cos\phi        & -\sin\phi \\
    \sin\phi       & \cos\phi
    \end{bmatrix}
    &
    \begin{bmatrix}
        0 & 0 \\
        0 & 0
    \end{bmatrix} \\
    \begin{bmatrix}
        0 & 0 \\
        0 & 0
    \end{bmatrix}
     & 
    \begin{bmatrix}
     \cos\theta        & -\sin\theta   \\
    \sin\theta        & \cos\theta 
    \end{bmatrix}
\end{pmatrix}
\cdot
\begin{pmatrix}
    \begin{bmatrix}
    *
    \end{bmatrix}
    &
    \begin{bmatrix}
        a & b \\
        c & d
    \end{bmatrix} \\
    \begin{bmatrix}
       *
    \end{bmatrix}
     & 
    \begin{bmatrix}
     *
    \end{bmatrix}
\end{pmatrix}
\cdot
\begin{pmatrix}
    \begin{bmatrix}
    \cos\phi        & \sin\phi \\
    -\sin\phi       & \cos\phi
    \end{bmatrix}
    &
    \begin{bmatrix}
        0 & 0 \\
        0 & 0
    \end{bmatrix} \\
    \begin{bmatrix}
        0 & 0 \\
        0 & 0
    \end{bmatrix}
     & 
    \begin{bmatrix}
     \cos\theta        & \sin\theta   \\
    -\sin\theta        & \cos\theta 
    \end{bmatrix}
\end{pmatrix}
$$

Let us denote the resulting top-right block by $    \begin{bmatrix}
        e & f \\
        g & h
    \end{bmatrix} $. Then we have the following system of equations. We will use this system many times later:
\begin{equation}\label{eq}
    \begin{cases}
    (a-d) \cdot \cos(\phi + \theta) + (a + d) \cdot \cos(\phi - \theta) - \\-(b+c) \cdot \sin(\phi + \theta) +  (b-c)\cdot \sin(\phi - \theta) = 2e\\
    (a-d) \cdot \sin(\phi + \theta) - (a + d) \cdot \sin(\phi - \theta) +\\+ (b+c)\cdot \cos(\phi + \theta) +  (b-c)\cdot \cos(\phi - \theta) = 2f\\
    (a-d) \cdot \sin(\phi + \theta) + (a + d) \cdot \sin(\phi - \theta) +\\+ (b+c)\cdot \cos(\phi + \theta) -  (b-c)\cdot \cos(\phi - \theta) = 2g \\
    -(a-d) \cdot \cos(\phi + \theta) + (a + d) \cdot \cos(\phi - \theta) +\\+ (b+c) \cdot \sin(\phi + \theta)+  (b-c)\cdot \sin(\phi - \theta) = 2h
    \end{cases}
\end{equation}

If we assume that this matrix is a fixed point, then we get a system of equalities 
where $a, b, c, d$ are fixed numbers for any $\phi, \theta$. But that is true only for $a, b, c, d = 0$. \par 

Indeed, we can take the first equality and the case when $\cos(\phi + \theta) =\sin(\phi - \theta) = 1$. Then $b = a + c + d$. After that we obtain a case when $\sin(\phi + \theta) =\cos(\phi - \theta) = 1$ and get $d = a + b + c$. Then $b = a + c +(a + b + c)$ and $a + c = 0$. If we also take $\cos(\phi + \theta) =-\sin(\phi - \theta) = 1$, then we get $c = a + b + d = a + (a + c + d) + d$ and $a + c = 2a + 2d = 0 = a + d$. Then $c = d$.
We get that other coefficients are equal to each other analogously, and all of them are 0, since their sum is 0.
\par 
So for a fixed point non-diagonal blocks can only be $0$. And the fact that $A_{\sigma, s}$ is a fixed point can be verified straightforward.

\end{proof}

Now to construct the GKM graph of $Q_{\G,\lambda}$ we have to find invariant 2-spheres. For $i < j \leq n$ let us introduce a vector subspace $U_{ij}\subset Q_{2n}$:
    $$ U_{ij} = \{A = (a_{k,l}) \, |\, a_{k,l} = 0 \; \text{unless}\; (k,l) \; \text{is in the block} \;(i,j) \; \text{or} \; (j,i)\},
    $$
    i.e.  only $a_{2i-1, 2j-1}, a_{2i-1, 2j}, a_{2i, 2j-1}, a_{2i, 2j} \not \eq 0$. This vector space can be decomposed in the sum of two subspaces $U_{ij} = U^{+}_{ij} \oplus U^{-}_{ij}$ such that for non-zero blocks $A$ and $B$ from $U^{+}_{ij}$ and $U^{-}_{ij}$ respectively:
    $$A \cong 
    \begin{bmatrix}
        \alpha & \gamma\\
        \gamma & -\alpha
    \end{bmatrix}, 
    B \cong 
    \begin{bmatrix}
        \alpha & \gamma\\
        -\gamma & \alpha
    \end{bmatrix}
    $$
    Indeed, $U_{ij}$ is a direct sum of this subspaces, since they are both 2-dimensional and intersect each other by 0.
\begin{prop}
    $U^{+}_{ij}$ and $U^{-}_{ij}$ are $T$-invariant irreducible real 2-dimensional representations with weights $\epsilon_i + \epsilon_j$ and $\epsilon_i - \epsilon_j$ respectively, where $\epsilon_1, \ldots, \epsilon_n$ is the standard basis of Hom$(T^n, S^1) \cong \mathbb{Z}^n$, that is $\epsilon_i((t_1, \ldots, t_n)) = t_i$ for $i = 1, \ldots, n$.
\end{prop}

\begin{proof}
    To verify this fact we should check that $U^{-}_{ij}$ (and $U^{+}_{ij}$) is $T$-invariant. We can use the system of equalities~\ref{eq} from the proof of Proposition~\ref{need} considering $a = d$ and $b = -c$. We get:

\begin{equation*}
\begin{cases}
    a \cdot \cos(\phi - \theta) + b\cdot \sin(\phi - \theta) = \alpha\\
     -a \cdot \sin(\phi - \theta) +  b\cdot \cos(\phi - \theta) = \gamma\\
    a \cdot \sin(\phi - \theta)  -  b\cdot \cos(\phi - \theta) = \delta \\
    a \cdot \cos(\phi - \theta) + b\cdot \sin(\phi - \theta) = \beta
\end{cases}
\end{equation*}
Since $\alpha = \beta$ and $\gamma = -\delta$, $U^{-}_{ij}$ is a 2-dimensional $T$-invariant representation. The weight of this representation is $\epsilon_i - \epsilon_j$, since

\begingroup\centering
\begin{equation*}
  \begin{bmatrix}
    \cos\phi        & \sin\phi \\
    -\sin\phi       & \cos\phi
    \end{bmatrix}
    \cdot
     \begin{bmatrix}
    a       & b \\
    -b       & a
    \end{bmatrix}
     \cdot
     \begin{bmatrix}
    \cos\theta       & \sin\theta \\
    -\sin\theta       & \cos\theta
    \end{bmatrix} =
\end{equation*}
\endgroup
\begingroup\centering
\begin{equation*}
    =\begin{bmatrix}
    a \cdot \cos(\phi - \theta) + b\cdot \sin(\phi - \theta) &
    -a \cdot \sin(\phi - \theta) +  b\cdot \cos(\phi - \theta)\\
    a \cdot \sin(\phi - \theta)  -  b\cdot \cos(\phi - \theta)  &
    a \cdot \cos(\phi - \theta) + b\cdot \sin(\phi - \theta)
    \end{bmatrix}
\end{equation*}
\endgroup

This representation is also irreducible. Indeed, assume it is not, then the subspace generated by blocks 
$$
     \begin{bmatrix}
    \alpha       & 0 \\
    0       & \alpha
    \end{bmatrix}$$ is a 1-dimensional representation and a $T$-invariant set. But if we take $\sin(\phi-\theta) = 1$ we will get an element 
    $
     \begin{bmatrix}
    0      & -a \\
    a      & 0
    \end{bmatrix}$
    that is not in this set, which is a contradiction.

    The case of $U^{+}_{ij}$ can be done analogously.
\end{proof}

For each fixed point we found two irreducible 2-dimensional tangent representations corresponding to every non-zero block of matrix, i.e. to every edge of the graph $\G$. So we found $2 \cdot |E_\G|$ representations at each point, and since dim $Q_{\G, \lambda} = 4|E_\G|$ we get a following proposition:

\begin{prop}
    At any fixed point $A_{\sigma, s}$ the tangent representation is  
    $$T_{A_{\sigma, s}}M_{\G, \lambda} = \bigoplus\limits_{\{i,j\}\in E_{\G}} U^+_{ij}\oplus U^-_{ij},$$
    with tangent weights of the form $ \{\epsilon_i + \epsilon_j, \epsilon_i - \epsilon_j\,|\, \{i,j\} \in \G\}$.
\end{prop}
    Now for each point we expect to find $2|E_\G|$ invariant 2-spheres. This will conclude a description of $Q_{\G, \lambda}$ GKM graph.

\begin{thm}
    If $\sigma = \tau \cdot (i,j)$ with $(i, j) \in E_{\G}$, where $s_k = s'_k$ for all $k \not \in \{i, j\}$ and $s_i + s_j = s'_i + s'_j$,
    then the matrices $A_{\sigma, s}$ and $A_{\tau, s'}$ are connected by a 2-sphere of isospectral matrices of the form
    $$
   \begin{pmatrix}
    \begin{bmatrix}
    0        & (-1)^{s_1} \cdot \lambda_{\sigma(1)} \\
    -(-1)^{s_1} \cdot\lambda_{\sigma(1)}       & 0 
    \end{bmatrix}
    & \hdotsfor[1.5]{4} &
    \begin{bmatrix}
        0 & 0 \\
