        0 & 0
    \end{bmatrix}
     & \hdotsfor[1.5]{4} &
     \begin{bmatrix}
    0        & (-1)^{s_n} \cdot\lambda_{\sigma(n)} \\
    -(-1)^{s_n} \cdot\lambda_{\sigma(n)}       & 0 
