\label{thm:intro-homog}
    Let $f\in K[x_1,\ldots,x_r]$ be a homogeneous polynomial of degree $\deg(f)\geq d\geq 1$, and let $\ell_1,\ldots,\ell_n$ be nonzero linear forms with $n\geq d$. 
    Then $f/(\ell_1\cdots\ell_n)$ has a PFD of degree $d$ as in

\begin{equation}\label{eqn:d PFD}
    \frac{f}{g}=\frac{f}{\ell_1\cdots\ell_n}=\sum_{\{j_1,\ldots,j_{n-d}\}\subset[n]} \frac{h_{j_1\cdots j_{n-d}}}{\ell_{j_1}\cdots\ell_{j_{n-d}}},\qquad \deg(\ell_i)=1,\,\deg(h_{j_1\cdots j_{n-d}})\leq \deg(f)-d.
\end{equation}

    if and only if $f$ vanishes to order at least $d-n+|S|$ on all flats $S$ of size at least $n-d+1$ of the hyperplane arrangement associated with the linear forms.,

theorem.content:
\label{thm:induced_subd_intro}
  Let $k,\,D\geq 2$ be integers and $H^\sigma$ be a subdivision of
  a graph $H$ with maximum degree $D$ and let $n=|V(H^\sigma)|$.  Then
  there exists an integer $n_0=n_0(k,D)$ such that for every
  $n\geq n_0$ the following hold.
  \begin{itemize}
  \item If $\sigma(e)$ is an even integer larger than
    $8\log_{D}n+Ck^7\log^2(kD)$ for any $e\in E(H)$, where~$C$ is a
    suitably large absolute constant, then
    \begin{equation*}
      \hat{R}_{\mathrm{ind}}(H^\sigma,k)={O(k^{342}
        \log^{9} (k) D^{9} \log D )n}.
    \end{equation*}

  \item If $\sigma(e)$ is an arbitrary integer larger than
    $12\log_{D}n+e^{Ck\log k}\log^2 D$ for any $e\in E(H)$, where~$C$
    is a suitably large absolute constant, then
    \begin{equation*}
      \hat{R}_{\mathrm{ind}}(H^\sigma,k)={e^{O(k\log k)}
        D^{9}\log (D)\, n}.
    \end{equation*}
  \end{itemize}

