The constant $8/\pi^2$ admits the following GCF representation:
\begin{equation}\label{eq:conjecture}
\frac{8}{\pi^2} = 1 - \cfrac{2 \cdot 1^4 - 1^3}{7 - \cfrac{2 \cdot 2^4 - 2^3}{19 - \cfrac{2 \cdot 3^4 - 3^3}{37 - \dots}}}
\end{equation}
where the partial denominators are $b_n = 3n^2+3n+1$ and partial numerators are $a_n = -(2n^4-n^3)$.,

ref_dict.thm:TopVexChar:
\begin{thm} \label{thm:TopVexChar}
    For any vexillary permutation $w$, $\hat{\mathfrak{G}}_w$ equals an integer multiple of $\chi_{D_{\text{top}}(w)}$.
\end{thm}

ref_dict.thm:topdeg-almostvex:
\begin{thm}
\label{thm:topdeg-almostvex}
    Let $w$ be any almost vexillary permutation.  Then $\hat{\mathfrak{G}}_w$ is a scalar multiple of $\chi_{{D}}$ for some diagram ${D}$.  In particular, $\text{Supp}(\hat{\mathfrak{G}}_w)$ is M-convex, and $\text{Newton}(\hat{\mathfrak{G}}_w)$ is a schubitope.  
\end{thm}

ref_dict.thm:chains:
\begin{thm}
    \label{thm:chains}
    If $w\in S_n$ is a dominant fireworks-vexillary chain, then $\supp(\mathfrak G_w)$ is precisely the set $\{\wt(\mathcal D)\colon \mathcal D \in \SBD(D(w), \emptyset,A)\}$ of weights of streamlined bubbling diagrams for some subset $A\subset D(w)$.  In particular, the homogenized Grothendieck polynomial $\widetilde{\mathfrak{G}}_w$ has M-convex support, and $\text{Newton}(\hat{\mathfrak{G}}_w)$ is a schubitope.
\end{thm}

post_theorem_intro_text:
\noindent Here $D_{\text{top}}(w)$ is a particular diagram which we will define in Section~\ref{sec:BubblingDiagrams}. 

Building on the results for vexillary permutations, we define new families of permutations which we call almost vexillary permutations and dominant fireworks-vexillary chains.  We show that for any almost vexillary permutation or dominant fireworks-vexillary chain, the support of the Castelnuovo-Mumford polynomial is indeed the set of integer points of a schubitope.  Specifically, we prove the following.
\begin{thm}
\label{thm:topdeg-almostvex}
    Let $w$ be any almost vexillary permutation.  Then $\hat{\mathfrak{G}}_w$ is a scalar multiple of $\chi_{{D}}$ for some diagram ${D}$.  In particular, $\text{Supp}(\hat{\mathfrak{G}}_w)$ is M-convex, and $\text{Newton}(\hat{\mathfrak{G}}_w)$ is a schubitope.  
\end{thm}
\begin{thm}
    \label{thm:chains}
    If $w\in S_n$ is a dominant fireworks-vexillary chain, then $\mathrm{supp}(\mathfrak G_w)$ is precisely the set $\{\mathrm{wt}(\mathcal D)\colon \mathcal D \in \mathcal{SBD}(D(w), \emptyset,A)\}$ of weights of streamlined bubbling diagrams for some subset $A\subset D(w)$.  In particular, the homogenized Grothendieck polynomial $\widetilde{\mathfrak{G}}_w$ has M-convex support, and $\text{Newton}(\hat{\mathfrak{G}}_w)$ is a schubitope.
\end{thm}

\textbf{Outline of the paper.} In Section~\ref{sec:BG}, we review the relevant definitions and background results.  In Section~\ref{sec:BubblingDiagrams}, we provide an overview of the bubbling diagram model for supports of vexillary Grothendieck polynomials.  We prove a simplified version of these bubbling diagrams in Section~\ref{sec:NewvexBubb} and use it to prove Theorem~\ref{thm:TopVexChar}.  In Section~\ref{sec:extendedBubb}, we define almost vexillary and dominant fireworks-vexillary chain permutations and prove Theorems~\ref{thm:topdeg-almostvex} and~\ref{thm:chains}.  More generally, we provide methods by which permutations whose Castelnuovo-Mumford polynomials have schubitope support can be combined into additional permutations with this property.

ref_dict.Thm2:
\begin{theorem}\cite[Proposition 6.2]{Coulson_2017}\label{Thm2}
For any nonnegative integer $J$ and $1\leq i\leq r$, we have
\begin{align}\label{ll1}
\mathcal{C}_{(r-1)J+\ell}(q)=\mathcal{E}_{r,i,J}(q),
\end{align}
where $\ell=r-i+1$.
\end{theorem}

ref_dict.Thm1:
\begin{theorem}[G\"ollnitz-Gordon-Andrews identities]\label{Thm1}
Let $r$ and $i$ be positive integers with $1\leq i\leq r$. Then $$C_{r,i}(n)=D_{r,i}(n)~~ \text{for~ all}~ n\geq0.$$
\end{theorem}

post_theorem_intro_text:
The case $r=2$ in Theorem~\ref{Thm1} yields the classical G\"ollnitz-Gordon identities, while the case $r=1$ leads to the trivial identity $1=1$. Throughout this article, we assume $r\geq2$.
\par For $1\leq i\leq r$, define
\begin{align}\label{1.1}
\mathcal{C}_i(q):=\prod_{\substack{m\geq1,~m\not\equiv2\pmod4\\ m\not\equiv0,~2r\pm(2i-1)\pmod{4r}}}\frac{1}{(1-q^m)}.
\end{align}
Here and throughout this article, we assume $\vert q\vert <1$. Note that $\mathcal{C}_{r-i+1}(q)$ is the generating function for $C_{r,i}(n)$.
For $g\geq1$, the series $\mathcal{C}_{(r-1)g+i}(q)$ is defined recursively (see \cite[Section 2]{Coulson_2017}) as follows. For $i=1$,
\begin{align*}
\mathcal{C}_{(r-1)g+1}(q)=\mathcal{C}_{(r-1)(g-1)+r}(q),
\end{align*}
and for $i=2,\ldots,r$,
\begin{align*}
\mathcal{C}_{(r-1)g+i}(q)=\frac{\mathcal{C}_{(r-1)(g-1)+r-i+1}(q)-\mathcal{C}_{(r-1)(g-1)+r-i+2}(q)}{q^{2g(i-1)}}-\frac{\mathcal{C}_{(r-1)g+i-1}(q)}{q}.
\end{align*}
Let $r$, $i$, and $J\geq0$ be integers with $1\leq i\leq r$. Let $E_{r,i,J}(n)$ denote the number of partitions $(\lambda_1,\lambda_2,\ldots,\lambda_s)$ of $n$ satisfying the following conditions:
\begin{enumerate}[1.]
\item No odd part is repeated,
\item $\lambda_m-\lambda_{m+r-1}\geq2$ if $\lambda_m$ is odd,
\item $\lambda_m-\lambda_{m+r-1}\geq3$ if $\lambda_m$ is even,
\item all parts are greater than $2J$, and
\item at most $i-1$ parts are equal to $2J+1$ or $2J+2$.
\end{enumerate} 
Let $\mathcal{E}_{r,i,J}(q)$ denote the generating function for $E_{r,i,J}(n)$. The following theorem, due to Coulson \textit{et al.} \cite{Coulson_2017}, generalizes the G\"ollnitz-Gordon-Andrews identities.
\begin{theorem}\cite[Proposition 6.2]{Coulson_2017}\label{Thm2}
For any nonnegative integer $J$ and $1\leq i\leq r$, we have
\begin{align}\label{ll1}
\mathcal{C}_{(r-1)J+\ell}(q)=\mathcal{E}_{r,i,J}(q),
\end{align}
where $\ell=r-i+1$.
\end{theorem}
The case $J=0$ in Theorem \ref{Thm2} gives the G\"ollnitz-Gordon-Andrews identities; hence Theorem \ref{Thm1} is a direct corollary of Theorem \ref{Thm2}. Note that $E_{r,i,0}(n)=D_{r,i}(n)$. For $J\geq 1$, however, no direct partition-theoretic interpretation of $\mathcal{C}_{(r-1)J+\ell}(q)$ is currently known, in contrast to the case $J=0$, where $\mathcal{C}_{\ell}(q)$ is the generating function of the partition function $C_{r,i}(n)$.
\par The aim of this article is to provide a proof of the G\"ollnitz-Gordon-Andrews identities using methods from commutative algebra. In fact, we establish the more general identities \eqref{ll1}. Our approach is inspired by a method recently employed by Afsharijoo \cite{Afsharijoo_2021}. Specifically, we study the identities in Theorem \ref{Thm2} by developing a relation between partitions and the Hilbert-Poincar\'e series of suitably constructed graded algebras.

