\end{align}
(and thus the main theorem): “The aim of this article is to provide a proof of the G\"ollnitz-Gordon-Andrews identities using methods from commutative algebra. In fact, we establish the more general identities the equation above. … Specifically, we study the identities in the theorem above by developing a relation between partitions and the Hilbert-Poincar\'e series of suitably constructed graded algebras.”

ref_dict.thm:entropy:
\begin{theorem}\label{thm:entropy}
Let $G$ be  finitely Liouville  non-hyper-FC-central group, and $k\geq 2$. Then there exists a sequence of non-degenerate symmetric probability measures $(\nu_n)_{n\geq 1}$ 
 on $G$ with finite entropy  such that  any $k-1$ convex combination of them is Liouville and any non-trivial $k$ or more (finite or infinite) convex combination of them is non-Liouville. 
 \end{theorem}

ref_dict.re:cont:
\begin{remark}\label{re:cont}
    Note that when $V'$, a set of probability measures,  admits a \emph{uniform first moment}, then  the map $V' \ni\mu\to H(\mu^{*n})$ is continuous in $\ell^1(G)$ \cite[Lemma A.1.]{Tanaka}. Under additional conditions on the group, the continuity of $\mu \to h(\mu) $ has been established in \cite{Kaimanovich-Erschler2013} and \cite{silva2025continuity}. However, the advantage of working with $\D$--metric is that no moment condition is needed for continuity $\mu \to H(\mu^{*n})$. 
\end{remark}

ref_dict.thm:B:
\begin{thm}[=Theorem~\ref{thm:entropy}]\label{thm:B}
For every finitely Liouville  non-hyper-FC-central group and $k\geq 2$,  there exists a sequence of symmetric, non-degenerate probability measures with finite entropy
such that any convex combination of $k-1$ of these measures is Liouville, and any other 
(finite or infinite) convex combination of them is non-Liouville.  
\end{thm}

ref_dict.thm:main1:
\begin{theorem}[=Theorem~\ref{thm:A}]\label{thm:main1}
Let $G$ be a countable non-hyper-FC-central amenable group. For every $k\geq 2$,  there exists a sequence of symmetric and non-degenerate probability measures $(\mu_m)_{m\geq1}$ such that $\mu = \sum_{m\geq 1} b_m \mu_m$ is non-Liouville if and only if the probability measure $b$ on $\NN$ has at least $k$ atoms. 
\end{theorem}

ref_dict.df:fittime:
\begin{definition}[\bf Fit time]\label{df:fittime}
Let $(\xi_i,\zeta_i)_{i\geq 1}$  be a sequence of i.i.d. random variables according to $\al_{t,p,q}$ (Definition~\ref{df:alpha}). Suppose that $\Phi$ is an $\alpha_{t,p,q}$--ladder as in Lemma~\ref{lem:phi}. We say   $(\xi_i,\zeta_i)_{i\geq 1}$ has a \emph{fit time} at time $n$   for $m$ whenever the following are satisfied:
\begin{enumerate}
\item $n<\Phi_m$, 
\item $(\xi_n, \zeta_n)=(m, 0)$,
\item  $\xi_i<m$ for all $i<n$.
\end{enumerate}
\end{definition}

ref_dict.thm:A:
\begin{thm}[= Theorem~\ref{thm:main1}]\label{thm:A}
For every non-hyper-FC-central countable amenable group  and every $k\geq 2$, there exists a sequence of symmetric, non-degenerate probability measures 
such that any convex combination of $k-1$ of these measures is Liouville, and any other 
(finite or infinite) convex combination of them is non-Liouville. 
\end{thm}

expanded_sketch:
The introduction explains that, to prove the main theorem, the argument uses both \emph{F{\o}lner sets} and \emph{switching sets}. It recalls that Kaimanovich--Vershik used F{\o}lner sets to construct Liouville measures, while Hartman--Frisch-Tamuz--Vahidi Ferdowsi used switching sets to construct non-Liouville measures. The measures in the main theorem are built \emph{inductively} by \emph{intertwining measures coming from F{\o}lner sets and switching sets}. The argument that the relevant convex combinations are \emph{non-Liouville} is said to follow from the general framework of Erschler--Kaimanovich, while the \emph{Liouville property of the extreme points} follows the strategy of Kaimanovich--Vershik. The main novelty is the construction itself, which relies on probabilistic notions called \emph{long gaps} and \emph{fit times}. 

\begin{definition}[\bf Long gap]\label{df:gap}The probability measure $\al_{t,p,q}$  (Definition~\ref{df:alpha}) has  a \emph{long gap} for $q$ whenever  there are infinitely many $m$ such that 
 $$
t\sum_{i=m}^\infty p_i \leq (1-t) q_m.
 $$
 \end{definition}

\begin{definition}[\bf Fit time]\label{df:fittime}
Let $(\xi_i,\zeta_i)_{i\geq 1}$  be a sequence of i.i.d. random variables according to $\al_{t,p,q}$ (Definition~\ref{df:alpha}). Suppose that $\Phi$ is an $\alpha_{t,p,q}$--ladder as in Lemma~\ref{lem:phi}. We say   $(\xi_i,\zeta_i)_{i\geq 1}$ has a \emph{fit time} at time $n$   for $m$ whenever the following are satisfied:
\begin{enumerate}
\item $n<\Phi_m$, 
\item $(\xi_n, \zeta_n)=(m, 0)$,
\item  $\xi_i<m$ for all $i<n$.
\end{enumerate}
\end{definition}
